programs.haiku:
"""Layer 1 MLP down_proj, component 3008.

A sparse feature: near 0 almost everywhere, large at a few kinds of places. From the
token text alone the program predicts:

  * the first token of each document (a document_ids change, or the row's first token):
    -0.25 (the measured mean there is about -0.23);
  * the colon in a document-opening "Title:": 9.5, the strongest activation seen;
  * the second piece of a G- or Q-prefixed science abbreviation, where the prefix is a
    lone capital G or Q: GCD, QCD, GTP, GDP, GMP, GFP, Gson and similar: about 3;
  * the whole token ' GDP': about 2;
  * a Chinese character that completes a two-character word whose first character is one
    of 地 (ground/place), 圖 (map), 志 (record), 皮, 記 (note), 氣 (air): about 0.8;
  * the middle-dot run '··': 0.56;
  * otherwise 0.
"""

READS = ()

DOC_START_VALUE = -0.25
TITLE_COLON_VALUE = 9.5
PREFIX_LETTERS = {"G", "g", "Q", "q"}
G_COMPLETIONS = {
    "CD", "TP", "DP", "MP", "CP", "TE", "CE", "CF", "STR", "FP", "SH", "TR", "CM", "SM", "son",
}
COMPLETION_VALUE = 3.0
WHOLE_TOKEN_VALUES = {"GDP": 2.0}
CJK_FIRST_CHARS = set("地圖志皮記氣")
CJK_SECOND_VALUE = 0.8
DOT_RUN_VALUE = 0.56


def _bare(text):
    """Token text without spaces or opening punctuation: ' G' and '(G' both give 'G'."""
    return text.strip().lstrip("(/-\"'")


def step(carry, prefix, upstream):
    ids = prefix.document_ids
    cur = prefix.token_strings[-1].strip()
    if len(ids) == 1 or ids[-1] != ids[-2]:
        return None, DOC_START_VALUE
    before = _bare(prefix.token_strings[-2])
    opens_doc = len(ids) == 2 or ids[-3] != ids[-2]
    if opens_doc and before == "Title" and cur == ":":
        return None, TITLE_COLON_VALUE
    if before in PREFIX_LETTERS and cur in G_COMPLETIONS:
        return None, COMPLETION_VALUE
    if cur in WHOLE_TOKEN_VALUES:
        return None, WHOLE_TOKEN_VALUES[cur]
    if len(cur) == 1 and before in CJK_FIRST_CHARS:
        return None, CJK_SECOND_VALUE
    if cur == "··":
        return None, DOT_RUN_VALUE
    return None, 0.0

"""Closing commas of mid-sentence interruptions (layer 1, MLP down_proj component 3010).

The component goes strongly negative on the punctuation that ends an aside inside a
sentence: the comma after "however", "I think", "of course", "for example", "he said",
and, more weakly, the second and later commas of a sentence (where an earlier comma has
opened an aside, an appositive or a relative clause). The first comma of a sentence,
commas inside number lists, and most other tokens are near zero. Closing parentheses,
em dashes and an opening quote right after a comma or period are mildly negative.

The program tracks, per document, how many commas have appeared in the current sentence
and how many tokens since the sentence began. It predicts:
  - comma after an earlier comma in the sentence: -0.13 - 0.45*exp(-tokens/30);
    extra -2.6 if the word before it is an aside word (however, think, said, example...);
  - ")" -0.3, dash -0.4, opening quote after "," or "." -0.6;
  - everything else 0.
"""

import math

READS = ()

SENTENCE_END = {".", "!", "?"}
ASIDE_WORDS = {
    "however", "therefore", "thus", "though", "indeed", "instead", "rather",
    "perhaps", "maybe", "course", "example", "instance", "think", "believe",
    "know", "say", "said", "says", "sure", "actually", "honestly", "frankly",
}
CLOSERS = {")", "）"}
DASHES = {"—", "–", "--"}
QUOTES = {'"', "“"}


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    word = tok.strip()
    new_doc = len(prefix.document_ids) < 2 or prefix.document_ids[-1] != prefix.document_ids[-2]
    if carry is None or new_doc:
        commas, dist = 0, 0
    else:
        commas, dist = carry
    prev = prefix.token_strings[-2].strip().lower() if not new_doc and len(prefix.token_strings) > 1 else ""
    value = 0.0
    if word == ",":
        if commas >= 1 and not prev[-1:].isdigit():
            value = -0.13 - 0.45 * math.exp(-dist / 30)
            if prev in ASIDE_WORDS:
                value -= 2.6
        commas += 1
    elif word in CLOSERS:
        value = -0.3
    elif word in DASHES:
        value = -0.4
    elif word in QUOTES and prev in (",", "."):
        value = -0.6
    if word in SENTENCE_END or "\n" in tok:
        return (0, 0), value
    return (commas, dist + 1), value

programs.sol:
"""Sparse responses to paths, escaping, and structured-text boundaries.

Common directory names following path separators are positive. Doubled backslashes are negative
as string escapes, but positive as TeX row breaks; their following newline
also gets a pulse. Smaller rules cover JSON keys, filename suffixes,
traceback line labels, headings, and the digits completing 30/31. Document
starts have separate rules for declaration words, Title:, and initial 12.
Everything else is zero. These rules omit the component's many weak lexical
responses. State is only the previous token, document position, and a short
text buffer, reset at document boundaries.
"""
import re

READS = ()
PATH_DIRECTORY_NAMES = {
    'workspace': 1.44, 'usr': 0.78, 'tmp': 0.70, 'opt': 1.55,
    'home': 1.95, 'Users': 1.90, 'root': 0.95, 'media': 1.35,
    'Volumes': 2.0, 'Applications': 1.65, 'scratch': 1.44,
    'Desktop': 1.2,
}
FILE_SUFFIXES = {
    '.json', '.yaml', '.yml', '.rs', '.mod', '.sh',
    '.jar', '.xml', '.conf', '.txt',
}
FUNCTION_WORDS = {
    'the', 'this', 'that', 'and', 'or', 'but', 'of', 'to', 'in',
    'for', 'with', 'on', 'at', 'as', 'is', 'it', 'was', 'were',
    'not', 'my', 'your', 'his', 'her', 'their', 'our',
}
TEX_COMMAND = re.compile(
    r'\\(?:begin|end|frac|sqrt|left|right|mathrm|mathbf|text|'
    r'alpha|beta|gamma|delta|sigma|lambda|theta|mu|eta|'
    r'nonumber|hline|hfill|qquad|quad|overline|pmatrix|'
    r'lim|sum|prod|int|sin|cos|tan|log|exp|cdot|color|ldots|'
    r'rightarrow|leftarrow|big|bigg|Big|Bigg)\b'
)
PRINT_OPEN = r'(?:print|printf|println|echo|log)\s*\(?'
ESCAPES = {
    'tex': 1.76,
    'quoted': -1.46,
    'triple': -0.37,
    'deep': -0.75,
    'formatted_string_start': -1.2,
    'string_start': -1.92,
    'raw_string': -0.88,
    'after_quote': -1.31,
    'other': -1.14,
}


def escape_kind(s, previous, recent):
    if '\\\\' not in s or any(c.isalnum() for c in s):
        return None
    if '"' in s or "'" in s:
        return 'quoted'
    if TEX_COMMAND.search(recent):
        return 'tex'
    if set(s.strip()) == {'\\'}:
        if len(s.strip()) == 3:
            return 'triple'
        if len(s.strip()) >= 4:
            return 'deep'
    if re.search(PRINT_OPEN + r'f\\"$', recent, re.I):
        return 'formatted_string_start'
    if re.search(PRINT_OPEN + r'\\"$', recent, re.I):
        return 'string_start'
    if re.search(PRINT_OPEN + r"['\"`][^'\"`]*$", recent, re.I):
        return 'raw_string'
    if previous.endswith('\\"'):
        return 'after_quote'
    return 'other'


def step(carry, prefix, upstream):
    doc, s = prefix.document_ids[-1], prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        previous, recent, position = '', '', 0
    else:
        _, previous, recent, position = carry
    value = 0.0
    word = s.lstrip('/\\')
    path = s.startswith(('/', '\\')) or previous.endswith(('/', '\\'))
    if path and word in PATH_DIRECTORY_NAMES:
        value = PATH_DIRECTORY_NAMES[word]
        if s.startswith('/'):
            value *= 0.5 if word == 'workspace' else 0.25
        elif previous.startswith('#!'):
            value *= 0.43
    elif s == '/local':
        value = 1.40
    elif s == '.github':
        value = 0.34
    elif s in FILE_SUFFIXES:
        value = -0.27
    elif s == '.md':
        value = -0.23
    elif s in {'.py', '.go', '.js'}:
        value = -0.08
    elif s in {'{"', ' {"'}:
        value = 0.46 if s == '{"' else 0.28
    elif s == '</tool_response>':
        value = -0.166
    elif s == '</think>':
        value = -0.108
    elif s == '··':
        value = 0.235

    kind = escape_kind(s, previous, recent)
    if kind:
        value = ESCAPES[kind]
    if previous.endswith('\\') and s in {'cr', 'non', 'h'}:
        value = {'cr': 4.0, 'non': 1.5, 'h': 1.25}[s]
    if s == 'line' and recent.endswith('\\h'):
        value = 1.65
    if s.isspace() and '\n' in s and recent.endswith('\\\\'):
        if TEX_COMMAND.search(recent):
            value = 1.05
    if s == ':\\' and len(previous) == 1 and previous.isascii():
        if previous.isalpha():
            value = 1.8
    if s == ' line' and previous == '\",' and 'File "' in recent[-160:]:
        value = 0.9

    if s == ' "':
        if previous == '\",':
            value = 0.22
        elif previous == '#include':
            value = 0.23
        elif previous.isspace() and recent.rstrip().endswith('{'):
            value = 0.60
        elif previous.isspace() and recent.rstrip().endswith(','):
            value = 0.24
    if s == '###' and previous == '\n\n':
        words = recent[:-2].split()
        if words:
            last = words[-1].strip(',;').replace('-', '')
            if last.islower() and last.isalpha():
                value = 0.35

    # Pulses on completing 30 or 31, especially in month-name dates.
    if previous == '3' and s in {'0', '1'}:
        value = -0.34 if s == '0' else -0.15
        if re.search(r'(January|February|March|April|May|June|July|August|'
                     r'September|October|November|December) 3$', recent):
            value = -0.85 if s == '0' else -0.65

    if position == 0:
        if s == 'int':
            value = 4.0
        elif s in {'from', 'FROM'}:
            value = 2.22 if s == 'from' else 1.86
        elif s in {'INT', 'string'} or s.startswith(('"""', "'''")):
            value = 1.7
        elif s in {'import', 'package', 'using', 'def', 'const', 'type'}:
            value = 0.85
        elif s == 'Title':
            value = 1.186
        elif s.isascii() and s.isdigit():
            value = 0.30
        elif s == 'The':
            value = -0.53
        elif (s in FUNCTION_WORDS or
              s.startswith(' ') and s.strip() in FUNCTION_WORDS):
            value = -0.35
    elif position == 1:
        if previous == 'Title' and s == ':':
            value = 5.924
        elif previous == '1' and s == '2':
            value = 3.679

    return (doc, s, (recent + s)[-320:], position + 1), value

"""Approximate spelling-fragment detector, not a detector of intentions.

Give negative responses to tokenized AIM and its inflections, to vowel+im
across a token boundary, and to diphthong+m in several alphabets. Case and
whether the stem is split change the strength. A few suffixes retain the
response. Weaker rules cover Chinese 目前, initial // comments, and a split
UTF-8 Han character after a space. Other positions are nearly zero.
"""

from functools import lru_cache
from anyascii import anyascii
import regex

READS = ()


@lru_cache(maxsize=32768)
def roman(text):
    if regex.fullmatch(r'[\p{Latin}\p{Greek}\p{Cyrillic}\p{M} ]+', text):
        return anyascii(text)
    return ''


def response(token, previous, was_aim, raw, previous_raw):
    word = token.lstrip(' ')
    lower = word.lower()
    if lower in ('aim', 'aims', 'aimed', 'aiming'):
        if not word.islower():
            return True, -8.1
        if lower in ('aims', 'aimed'):
            return False, -4.25
        return True, -6.0 if token.startswith(' ') else -7.3

    current, before = roman(token), roman(previous)
    small, ending = current.lower(), before[-1:].lower()
    if token == 'им':
        if ending == 'a':
            return True, -8.0
        if ending == 'e':
            return False, -4.5
        if ending in ('o', 'u'):
            return False, -2.8
        return False, -0.9 if ending == 'n' else 0.05

    if small.startswith('im') and len(current) <= 4:
        if before.endswith('A'):
            return True, -12.0 if small == 'im' else -9.3
        if ending == 'a':
            return True, -5.0 if small == 'im' else -6.5
        if ending in ('e', 'o', 'i', 'j'):
            return False, -0.6 if ending == 'e' else -1.3
        return False, 0.1

    if small.startswith('m'):
        if before.lower().endswith(('ai', 'aj', 'ay', 'ei', 'ej', 'ey',
                                    'oi', 'oj', 'oy')):
            if token.startswith(('м', 'М')):
                return False, -6.5 if len(token) == 1 else -3.5
            if before.lower().endswith('y'):
                return False, -1.2
            return False, -4.6 if small == 'm' else -1.8
        if ending in ('i', 'j', 'y'):
            return False, -0.25
    if small.startswith('i') and ending == 'a':
        return False, -2.7 if small == 'ip' else -0.12

    if was_aim:
        if token == 'S' and previous.endswith('AIM'):
            return False, -9.8
        if token in ('an', 'ed', 'er'):
            return False, -4.5
        if token == ' of':
            return False, -0.88
    if token == '目前':
        return False, -1.15
    if token == '//\n' and not previous:
        return False, -3.1
    if previous_raw == b' \xe9' and len(raw) == 1 and 0x80 <= raw[0] < 0xc0:
        return False, 0.6
    return False, -0.002


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token, raw = prefix.token_strings[-1], prefix.token_bytes[-1]
    if carry is None or carry[0] != doc:
        previous, was_aim, previous_raw = '', False, b''
    else:
        previous, was_aim, previous_raw = carry[1:]
    matched, value = response(token, previous, was_aim, raw, previous_raw)
    return (doc, token, matched, raw), value

"""Approximate the negative response to 'ld' in short pieces of words.

The vowel before ld sets its strength: i is strongest, a/e intermediate,
o very weak. Common English words normally switch the response off, but
mild and wild retain it. A short continuation inherits part of the response.
Also recognize l+ch (positive), soft Cyrillic l+d, and double middle dots.
"""
from wordfreq import zipf_frequency

READS = ()


def cluster_value(token, previous):
    s, p = token.strip().lower(), previous.lower()
    if s == '··':
        return -2.1
    if p.endswith('ль') and token.startswith('д'):
        return -3.8
    if p.endswith(('л', 'ль')) and token.startswith('ч'):
        return 1.3
    if p.endswith('l') and token.lower() == 'ch':
        return 1.6
    linked = token[:1].isalpha() and previous[-1:].isalpha()
    cross = p.endswith('l') and token.lower().startswith('d')
    if 'ld' not in s and not cross:
        return 0.0
    word = previous.strip().lower() + s if linked else s
    if s == 'mild':
        return -5.5
    if s == 'mildly':
        return -3.6
    if s == 'wild':
        return -1.7
    if s == 'field' and linked:
        return -1.3
    if zipf_frequency(word, 'en') >= 4.4:
        return -0.05
    # et|ilde is usually the end of a TeX tilde command.
    if s == 'ilde' and p.endswith('et'):
        return -0.8
    if s == 'ld' and previous.endswith('\\'):
        return -0.7
    if cross and token.istitle() and len(s) > 1:
        return -0.05  # CamelCase starts a new word, not an ld cluster.
    if cross:
        return -4.5 if len(s) <= 4 else -0.1

    j = s.index('ld')
    before = s[:j]
    if before.endswith(('ui', 'ie', 'ou')):
        return -0.1
    strength = 3.3
    if before.endswith('i'):
        strength = 5.7
    elif before.endswith('o'):
        strength = 0.2
    elif before.endswith(('u', 'ı')):
        strength = 1.8
    if j > 1:
        strength *= 0.6
    if len(s) - j - 2 > 2:
        strength *= 0.3
    return -strength


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    previous, old_value = ('', 0.0)
    if carry is not None and carry[0] == document:
        _, previous, old_value = carry
    token = prefix.token_strings[-1]
    base = cluster_value(token, previous)
    value = base
    if ('ld' in previous.lower() and token[:1].isalpha()
            and previous[-1:].isalpha() and len(token) <= 4):
        value += old_value * (0.65 if token in ('s', 'es', 'is') else 0.23)
    return (document, token, base), value

"""A spelling detector for n followed by i, especially short nit/knit fragments.

The pair can straddle a token boundary or begin the current fragment. The
following letters and fragment length set the response; ie/ick can be
positive. The previous fragment modifies its strength. Other tokens get zero.
Accents are folded and Cyrillic letters are transliterated by dictionary.
"""
import re
import string
import unicodedata
from functools import lru_cache
from anyascii import anyascii

READS = ()

@lru_cache(maxsize=65536)
def spelling(text):
    text = ''.join(c for c in unicodedata.normalize('NFD', text.lower())
                   if unicodedata.category(c) != 'Mn').replace('ı', 'i')
    if any('CYRILLIC' in unicodedata.name(c, '') for c in text):
        text = anyascii(text)
    return text

# Strength by letter following i: short, medium, and long fragments.
RESPONSES = (
    ('t', (-6.39, -3.24, -1.63)),
    ('d', (-2.71, -1.96, -1.35)),
    ('sz', (-3.89, -1.37, -0.69)),
    ('pf', (-2.09, -0.99, -0.37)),
    ('ghjlmnrx', (-1.2, -0.5, -0.2)),
    ('aouy', (-0.3, 0.1, 0.0)),
)


def response(tail):
    if tail == 'i':
        return -0.69
    if tail == 'ity':
        return -1.15
    if tail.startswith('ie'):
        return 0.25
    if tail.startswith('ick'):
        return 0.64
    if tail.startswith(('ic', 'ik')):
        soft = len(tail) > 2 and tail[2] in 'eiyh'
        return -0.24 if soft else 0.01
    # Discount doubled consonants; knit inflections remain medium-length.
    length = len(tail)
    if length > 2 and tail[1] == tail[2]:
        length -= 1
    if tail.startswith('itt') and tail.endswith(('ing', 'ed')):
        length = 3
    bucket = 0 if length <= 2 else 1 if length == 3 else 2
    for letters, strengths in RESPONSES:
        if tail[1:2] in letters:
            return strengths[bucket]
    return (-0.24, -0.31, -0.08)[bucket]


def step(carry, prefix, upstream):
    original = prefix.token_strings[-1]
    current = spelling(original)
    previous = ''
    if prefix.position and prefix.document_ids[-2] == prefix.document_ids[-1]:
        previous = spelling(prefix.token_strings[-2])
    value = 0.0
    if current.startswith('i') and previous.endswith('n'):
        word = re.search(r'[a-z]+$', previous).group()
        if word == 'n':
            scale = 1.0
        elif word.endswith('kn'):
            scale = 1.8
        elif word.endswith('nn'):
            scale = 1.2
        else:
            scale = 0.8
        value = scale * response(current)
    else:
        word = current.lstrip(string.whitespace + string.punctuation)
        if word.startswith('kni'):
            value = response(word[2:])
        elif word.startswith('ni'):
            boundary = current != word or original[:1].isupper()
            scale = 0.9 if boundary else 0.6
            value = scale * response(word[1:])
    return None, float(value)

programs.haiku:
"""Layer-1 MLP down_proj component 3016: a sparse, token-specific predictor.

The component is silent almost everywhere (it fires on about 0.009% of tokens). When it
fires, the largest cases are a few kinds of token:

- cost and device nouns, read as positive: 装置 (device), 费 / 費 (fee, cost),
  消费 (consumption), 品质 (quality), 指标 (index, quota);
- runs of repeated middle dots (leader lines, as in ASCII tables), read as a
  moderate positive;
- a few verbs and nouns read as negative: 合作 (cooperate), 模 (model), 支持
  (support), 更多 (more);
- a symbol that opens a new document, right after <|endoftext|> (such as '#' or 'A'),
  read as negative.

Everything else predicts 0. This is a short list of the strongest cases, not a full
account of the component: most of its variance is not covered by any simple rule.
"""

READS = ()

COST_DEVICE = {"装置", "费", "費", "消费", "品质", "指标"}
NEGATIVE = {"合作", "模", "支持", "更多"}
DOCUMENT_SYMBOLS = {"#", "A"}


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    if tok in COST_DEVICE:
        return None, 1.0
    if tok == "··":
        return None, 0.7
    if tok in NEGATIVE:
        return None, -0.4
    if len(prefix.token_strings) > 1 and prefix.token_strings[-2] == "<|endoftext|>" and tok in DOCUMENT_SYMBOLS:
        return None, -0.8
    return None, 0.0

programs.sol:
"""A sparse spelling response centered on Arabic waw (و).

Waw alone or beside a vowel is strongly positive, especially in Arabic
rather than Persian spelling. Longer merged words usually do not fire.
Short Latin wa/aw fragments are positive and wo/vo negative. A single
vowel or Arabic vowel mark can continue a preceding fragment's response.
Repeated middle dots receive a small positive value. Otherwise the output
is zero. These are approximate spelling rules, not a phonetic transcription.
"""
import unicodedata

READS = ()
# Spelling markers shared by Persian and several related writing systems.
PERSIAN_LETTERS = frozenset('پچژگکی')
VOWELS = frozenset('ايىی')


def predict(token, previous, old_value=0.0, persian=False):
    s, p = token.strip(), previous.rstrip()
    joined = token == s
    value = 0.0
    if 'و' in s and len(s) <= 4:
        if s == 'و':
            value = (3.3 if persian else 6.4) if joined else (
                2.7 if persian else 4.8)
        elif len(s) == 2 and s.endswith('و'):
            value = 3.0 if persian else 4.3
            if not joined:
                value *= 0.6
            if s[0] in VOWELS:
                value *= 0.4
            if s[0] == 'أ':
                value = 3.4
        elif s.startswith('و'):
            if not joined:
                value = 2.4 if s == 'وال' else (1.5 if len(s) == 2 else 0.8)
            elif s[1] in VOWELS or s[1] == 'ء':
                value = (4.1 if persian else 5.8) if len(s) == 2 else 2.4
                if len(s) == 3 and s[-1] in 'ةت':
                    value = 4.2
            elif len(s) == 2:
                value = 3.1 if s[-1] in 'ةه' else (2.2 if s[-1] == 'ت' else 0.5)
        elif len(s) == 3 and s.endswith('وا'):
            value = 3.0
        if joined and s.startswith('و') and p and p[-1] in VOWELS:
            value *= 0.6
    # A vowel or mark may be tokenized separately from its waw fragment.
    elif joined and 'و' in p and len(p) <= 3 and s:
        if all(unicodedata.combining(c) for c in s):
            value = 0.65 * old_value
        elif len(s) == 1 and s in VOWELS | {'ة'}:
            value = 0.7 * old_value
        elif p.endswith('و') and s[0] in VOWELS:
            value = 0.25 * old_value

    l = s.lower()
    if l in ('awa', 'awi'):
        value = 1.8 if l == 'awa' else 2.8
    elif l in ('wo', 'owo', 'vo'):
        value = -0.6 if l == 'vo' else -1.0
    elif l in ('wa', 'aw'):
        value = 0.9 if l == 'wa' else 0.7
        if not joined:
            value *= 0.6
        if s == 'WA':
            value = 2.0
    elif joined:
        if l in ('w', 'we'):
            value = 0.15
        elif l in ('a', 'e', 'o') and p.lower().endswith(('w', 'v', 'u')):
            value = -0.8 if l == 'o' else (1.2 if l == 'a' else 0.6)
    if s and set(s) == {'·'} and len(s) >= 2:
        value = 0.7
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous, old_value, persian = '', 0.0, False
    if carry is not None and carry[0] == doc:
        _, previous, old_value, persian = carry
    token = prefix.token_strings[-1]
    persian = persian or bool(PERSIAN_LETTERS.intersection(token))
    value = predict(token, previous, old_value, persian)
    return (doc, token, value, persian), float(value)

"""Sparse approximation of document-start and text-layout responses.

An initial NUL or literal USE has a large positive response; the second
digit of an initial 12 has a negative one. A single-space token after a
real or escaped newline is positive. Elsewhere use small position-based
baselines. Later NULs have a small negative baseline. Most token-specific
background variation is deliberately left unexplained.
"""
READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        position, previous, before_previous = 0, b'', b''
    else:
        _, position, previous, before_previous = carry
    token = prefix.token_bytes[-1]
    state = (doc, position + 1, token, previous)
    if token == b'\x00':
        return state, 2.70 if position == 0 else -0.024
    if position == 0:
        if token == b'USE':
            return state, 1.18
        return state, 0.07
    if position == 1 and previous == b'1' and token == b'2':
        return state, -1.16
    if token == b' ':
        if previous.endswith(b'\\n') or (previous == b'n' and
                                          before_previous.endswith(b'\\')):
            return state, 0.56
        if previous.endswith(b'\n'):
            return state, 0.21
    if position <= 2:
        return state, -0.006
    return state, 0.0015

"""Approximate a sparse, document-opening pattern response.

Large positive responses mark an opening '12', scientific 'Hydro-' prefix,
template '{[', or JavaScript '(function ()'. The leading number's response
fades on additional twos. A run of eight colons gets a smaller positive
response. Elsewhere, use near zero, with coarse word-class offsets on the
first token. Weak, idiosyncratic token effects are deliberately omitted.
"""
READS = ()

# English closed-class words: articles, pronouns, auxiliaries and connectives.
FUNCTION_WORDS = set('''
a an the of in on at by for to from with without as and or but nor if
then than is are was were be been being do does did has have had will
would can could may might must shall should it its he she they them
their we our you your I that this these those what which who when
where why how not no so
'''.split())


def opening_bias(token):
    word = token.strip()
    if token == '1':
        return 0.162
    if not word:
        return -0.17 if '\n' in token or '\r' in token else 0.015
    if word.isdecimal():
        return -0.12
    if word in FUNCTION_WORDS:
        return -0.073
    if word.isalpha():
        return -0.35 if token.startswith(' ') else -0.25
    if not any(c.isalnum() for c in word):
        return -0.15
    return -0.265


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        pos, previous, opening = 0, '', token
    else:
        _, old_pos, previous, opening = carry
        pos = old_pos + 1
        opening = opening + token if pos <= 3 else ''

    value = opening_bias(token) if pos == 0 else -0.001
    if pos == 1:
        if previous == '1' and token == '2':
            value = 3.412
        elif previous == 'Hy' and token == 'dro':
            value = 3.04
        elif previous == '{' and token == '[':
            value = 1.45
        elif previous == '(function' and token == ' ()':
            value = 1.74
    elif pos == 2 and opening == '122':
        value = 1.294
    elif pos == 3 and opening == '1222':
        value = 0.302
    if pos > 0 and token.strip() == ':' * 8:
        value = 0.726
    return (doc, pos, token, opening), value

"""A small collocation detector for finding things and expressing uncertainty.

The strongest response is negative on 'out' in 'find out'. Finding oneself,
locations of things found, and search-method suffixes have positive responses.
Idea/doubt expressions and a few fixed English constructions are negative.
Only the previous token and a short spelling tail are remembered; documents reset.
These rules approximate the large responses, not every weak lexical effect.
"""
import re

READS = ()
_FIND = {'find', 'finds', 'found', 'finding'}
_SELF = {'myself', 'yourself', 'himself', 'herself', 'itself',
         'ourselves', 'yourselves', 'themselves'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    text = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        previous, tail = '', ''
    else:
        _, previous, tail = carry
    word = text.strip().lower()
    prev = previous.strip().lower()
    combined = tail + text
    value = 0.0

    if prev in _FIND:
        if word == 'out':
            value = -10.3 if previous.strip() == 'Find' else -8.9
        elif word in _SELF:
            value = 2.6 if word.endswith('selves') else 3.6
        elif word == 'in':
            value = 0.9
        elif word == 'it':
            value = 0.5
    if (previous.endswith(('.find', '.Find', '/find')) or
            (prev in {'find', '_find'} and not text[:1].isspace())):
        if re.match(r'[_-]?(all|first|last|index|up|in|next)(?:$|[_-])', word):
            value = 5.0
        elif text in {"('", '("'}:
            value = 3.5

    if word == 'doubt':
        value = -3.2 if prev in {'no', 'a', 'any', 'in'} else -0.6
    elif word in {'idea', 'clue'}:
        if prev == 'no':
            value = -4.0 if word == 'idea' else -6.0
        elif prev in {'any', 'an', 'a'}:
            value = -2.6 if word == 'clue' else -1.2
    elif word in {'error', 'mistake', 'misunderstanding'}:
        if prev in {'a', 'an'}:
            value = -0.35
    elif prev == 'no' and word == 'evidence':
        value = -0.8
    elif prev == 'in' and word in {'between', '-between'}:
        value = -2.6
    elif prev == 'couple' and word == 'of':
        value = -0.8

    # Spelling-completions of European words for idea or doubt.
    if previous and previous[-1].isalpha() and text and text[0].isalpha():
        if re.search(r'\b(idée[s]?|idee[n]?|ideia[s]?|idea[s]?)$',
                     combined, re.I):
            value = -3.4
        elif re.search(r'\b(doute[s]?|duda[s]?|dubbio)$', combined, re.I):
            value = -4.8
    if prev == 'tìm' and word == 'hiểu':  # Vietnamese: find out / learn about
        value = -4.8

    return (doc, text, combined[-32:]), value

programs.haiku:
"""layers.1.mlp.down_proj:3020, a "finding out / not knowing" word detector.

The component is silent almost everywhere. It fires on the word that completes a few
set phrases about discovering or not knowing something:

- "find out" (the word "out" right after "find"/"found"/"finding"): strongly negative,
  about -9. "Find out how...", "to find out what..." are the usual cases.
- "no idea", "no clue", "no doubt" (and "a doubt"): negative, about -4. The same
  words elsewhere are weaker (about -1.5), so the preceding word matters.
- Doubt and idea words in other languages: "sin duda", "sans doute", "dubbio",
  "idée", "ideia", and Vietnamese "tìm hiểu" (look into / research): negative, about -3 to -5.

It is mildly positive on "find yourself" / "find herself" (about +4), and on the code
method "find_all" (about +4). Everything else predicts 0.

The program reads the text word by word, with a carry holding the previous and the
current word. The carry resets at each document boundary.
"""

import re

READS = ()

FIND_WORDS = {"find", "finds", "found", "finding"}
NO_WORDS = {"no", "a", "sin", "sans", "senza", "ohne", "without"}
DOUBT_WORDS = {"idea", "idée", "idee", "ideia", "clue", "doubt", "doute", "duda", "dubbio"}
REFLEXIVE = {"yourself", "herself", "myself"}
LETTER_RUN = re.compile(r"[^\W\d_]+")


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    if carry is None or carry["doc"] != doc:
        carry = {"doc": doc, "prev": "", "cur": "", "open": False}
    prev, cur = carry["prev"], carry["cur"]

    # Track words: a token that starts with a letter, right after a letter, continues the
    # current word; anything else closes it.
    runs = LETTER_RUN.findall(token.lower())
    if token[:1].isalpha() and carry["open"]:
        cur = cur + (runs[0] if runs else "")
    else:
        if cur:
            prev = cur
        cur = runs[0] if runs else ""
    opened = token[-1:].isalpha()

    value = 0.0
    if cur == "out" and prev in FIND_WORDS:
        value = -9.0
    elif cur in DOUBT_WORDS:
        value = -4.0 if prev in NO_WORDS else -1.5
    elif cur == "hiểu" and prev == "tìm":
        value = -3.0
    elif cur in REFLEXIVE and prev in FIND_WORDS:
        value = 4.0
    elif cur == "all" and token.startswith("_") and prev == "find":
        value = 4.0

    carry = {"doc": doc, "prev": prev, "cur": cur, "open": opened}
    return carry, float(value)

programs.sol:
"""Short n--vowel--s spellings, especially the suffix nes(s).

Predict negative responses to these subword fragments and to their
continuations across token boundaries. Whole lexicalized words usually
get little response, except for the conspicuous 'fitness' spelling.
Common established -ness words are attenuated by word frequency.
Historical long-s and a few non-Latin pronunciations follow the same
pattern. Hungarian n-vowel fragments have the opposite sign.

Token length is a rough proxy for how visibly a token exposes the ending;
this is an approximation, not a general rule for every word ending in ness.
"""
import re
from functools import lru_cache
from anyascii import anyascii
from wordfreq import zipf_frequency

READS = ()
HUNGARIAN = re.compile(r'\b(és|egy|hogy|meg|nem|vagy|az)\b|[őű]')


@lru_cache(maxsize=20000)
def transliteration(text):
    return anyascii(text).lower().strip()


@lru_cache(maxsize=20000)
def common_ness(stem):
    word = re.search(r'[a-z]+$', stem)
    return bool(word and zipf_frequency(word[0] + 'ness', 'en') > 4.2)


def response(raw, previous, history, first, screen=True):
    t, p = raw.strip().casefold(), previous.strip().casefold()
    hungarian = bool(HUNGARIAN.search(history.lower()))
    # Productive suffix fragments, versus fused whole words.
    if t == 'ness':
        if screen and common_ness(p):
            return -0.2
        if p.endswith('ed') and len(p) > 6:
            return -0.7
        return -3.1 if len(p) <= 6 else -1.5
    if t == 'nes':
        return -0.4 if p.endswith(('è', 'é', 'ê', 'ô')) else -3.8
    if t == 'nis':
        return -1.4
    if t == 'nass':
        return -1.9
    if t in ('fitness', 'itness'):
        return -1.8 if raw.strip().isupper() else -4.1
    if t in ('iness', 'eness', 'leness'):
        return -1.8
    if re.fullmatch(r'[aeiou]n{1,2}[ei]s', t):
        return -2.3 if 'nn' in t else -0.5
    if t.endswith('ness'):
        return -0.7 if len(t) < 8 else -0.14

    # A syllable may straddle the token boundary.
    if raw and not raw[0].isspace():
        if history.lower().endswith(('neſ', 'niſ')) and t == 's':
            return -8.8 if history.lower().endswith('neſ') else -3.5
        if p.endswith('nes') and t in ('s', 'se'):
            return -3.5
        if p.endswith('neff') and t == 'es':
            return -3.0
        if p.endswith('n'):
            if t == 'ess':
                return -4.1
            if t == 'es':
                return -2.0 if len(p) <= 3 else -0.4
            if re.fullmatch(r'is(?:s(?:e[ns]?)?|[cthkm]s?)?', t):
                if len(p) > 3:
                    return -0.2
                return -2.5 if t.startswith('iss') else -1.2
            if t.startswith('es') and len(t) <= 5:
                return -0.7 if t.startswith('est') else -2.0
            if t in ('ass', 'oss', 'uss'):
                return -2.0
            if len(p) <= 2 and t == 'ss':
                return -2.0
        if p.endswith(('ne', 'ni')) and t in ('s', 'ss', 'fs'):
            return -3.9 if p.endswith('ne') else -3.5
        # Opposite-sign n-vowel continuations in names and Hungarian.
        if ((p.endswith('rn') and t in ('i', 'ia'))
                or (p.endswith('r') and t == 'nia')):
            return 2.3
        if previous.strip() == 'N' and re.fullmatch(r'[aeiou]+n?[aeiou]+', t):
            return 2.3
        if hungarian and (t in ('ni', 'ne', 'nia', 'ania', 'ani')
                          or (t == 'i' and p.endswith('n'))):
            return 2.8
        # Kana/Cyrillic syllables and Chinese name-transcription characters.
        if previous.endswith(('ネ', 'ニ', 'ナ')) and raw in ('ス', 'ズ', 'ーズ'):
            return -8.0 if previous.endswith('ネ') else -2.2
        if p.endswith(('не', 'ни')) and t in ('с', 'сс'):
            return -3.8
        if previous.endswith('尼') and raw in ('斯', '丝', '絲', '西'):
            return -2.5
    if hungarian and t == 'ne':
        return 2.3
    if t == 'né':
        return 6.3 if hungarian else 1.1
    if not raw.isascii() and transliteration(raw) in ('nes', 'nisi', 'nis'):
        return -3.0
    return 0.14 if first else 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    previous, history = ('', '') if first else carry[1:]
    raw = prefix.token_strings[-1]
    value = response(raw, previous, history, first)
    return (doc, raw, (history + raw)[-100:]), float(value)

"""Approximate noun-phrase/complement signals in English.

The strongest negative response is to a means of doing something ('an easy
way', 'the only way'), not manner idioms ('in a way').  Related rules cover
occasions, reasons, opportunities and nominal 'need', and the following 'to'.
WordNet identifies adjectival modifiers; function words and numbers are
excluded. Assistant headers, initial code comments, escaped quotes and
backslash-newline tokens have separate rules. This is not a full parser:
only four recent tokens are retained, reset per document.
"""
from functools import lru_cache
import wordnet

READS = ()
COPULA = set("is are was were be been being 's ’s".split())
DETERMINER = set('a an the no any some another one'.split())
POSSESSIVE = set('my your his her its our their this that these those'.split())
PREPOSITION = set('in on by along through'.split())
FUNCTION_WORDS = (DETERMINER | POSSESSIVE | PREPOSITION |
                  set('of to for and or not so as at with without after before '
                      'up down out only both all same either each every more less '
                      'most least many much few several still other there '
                      'then now'.split()))
NOUNS = set('way ways time times reason reasons need opportunity opportunities '
            'chance chances place places answer solution alternative possibility '
            'example attempt ability'.split())


@lru_cache(maxsize=4096)
def adjective(word):
    return (word not in FUNCTION_WORDS and not word.isdigit() and
            not wordnet.is_a(word, 'number') and
            ('adjective' in wordnet.parts_of_speech(word.lstrip('-'))
             or word == 'fun'))


def noun_value(word, history, raw_previous):
    if word not in NOUNS:
        return 0.0
    # The last three tokens, oldest first.
    older, before, last = ([''] * 3 + history)[-3:]
    existential = 'there' in history and any(w in COPULA for w in history)
    nominal = last in DETERMINER or adjective(last)
    manner = (last in POSSESSIVE or
              last in {'same', 'either', 'both', 'other', 'some', 'two'} or
              before in PREPOSITION or
              (before in {'a', 'an', 'the'} and older in PREPOSITION)
              or before == 'such' or older == 'such')
    if word == 'way':
        if manner:
            return 0.1
        if last == 'only':
            return -6.2
        if last in {'easy', 'easier', 'easiest'}:
            return -5.0
        if last in {'best', 'better'}:
            return -3.7
        if existential:
            return -4.8
        if last in {'a', 'an'}:
            if before in {'have', 'has', 'had'}:
                return -0.4
            return -3.1 if before in COPULA else -2.3
        if last in {'one', 'another', 'no'}:
            return -3.8 if raw_previous.lstrip()[:1].isupper() else -2.4
        if adjective(last):
            modified = (before in DETERMINER or
                        before in {'most', 'more', 'less', 'very'} or
                        last.startswith('-'))
            return -2.6 if modified else -1.0
        return 0.12 if last == 'the' else -0.2
    if word == 'ways':
        if last in POSSESSIVE or last in {'both', 'all', 'in', 'two'}:
            return 0.05
        if existential:
            return -3.5
        if last == 'of' and before == 'number' or last == 'the' and before == 'of':
            return -2.5
        if adjective(last):
            return (-0.55 if last in {'different', 'new', 'various', 'other'}
                    else -1.5)
        return -0.8
    if word in {'time', 'times'}:
        if existential:
            return -3.8 if word == 'times' else -2.5
        if word == 'times':
            if last in {'still', 'good'}:
                return -3.5
            return -0.8 if last in {'many', 'more', 'of', 'the'} else 0.0
        if last in {'last', 'next', 'first'}:
            if before == 'the':
                return -0.6 if older == 'for' else -2.4
            return -1.1
        if last == 'every':
            return -1.25
        if last == 'each':
            return -0.4
        if last == 'any':
            return -2.3 if raw_previous.lstrip()[:1].isupper() else -0.5
        if last in {'second', 'third', 'fourth'}:
            return -1.0
        if last in {'best', 'perfect', 'right', 'wonderful'} and before == 'the':
            return -3.0
        if last == 'the' and before in COPULA:
            return -1.3
        if (last in {'a', 'an', 'no'} or
                adjective(last) and before in {'a', 'an', 'the'}):
            return -0.6
        return 0.1
    if word in {'reason', 'reasons'}:
        if last in POSSESSIVE or 'for' in {before, older}:
            return 0.0
        if existential:
            return -2.7
        if last in {'a', 'no', 'one', 'another'} or adjective(last):
            return -1.8
        return -1.1 if last == 'the' else -0.2
    if word == 'need':
        if last in {'a', 'no'}:
            return -2.2 if existential else -1.6
        return -0.9 if last == 'the' else 0.05
    if word in {'opportunity', 'opportunities', 'chance', 'chances'}:
        if existential:
            return -2.6
        if before in {'have', 'has', 'had'}:
            return -0.2
        if adjective(last):
            return -0.6 if word in {'opportunities', 'chances'} else -1.8
        if last in {'a', 'an'}:
            return -1.2
        return -0.4 if last == 'the' else -0.2
    if word in {'place', 'places'}:
        if manner or last in {'decimal', 'binary', 'significant'}:
            return 0.0
        if last == 'no' or last in {'good', 'great', 'best', 'ideal', 'friendly'}:
            return -2.2
        if adjective(last) and last != 'first':
            return -0.5
        return -1.0 if last in {'a', 'an'} else -0.1
    if word == 'answer':
        if last in DETERMINER:
            return -0.8
        return -1.0 if adjective(last) and before == 'the' else 0.0
    if word in {'solution', 'alternative', 'possibility', 'example',
                'attempt', 'ability'}:
        return -0.35 if nominal else 0.0
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        history, previous, last_value = [], '', 0.0
    else:
        _, history, previous, last_value = carry
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    prev = history[-1] if history else ''
    boundary = not history or token[:1].isspace() or previous[-1:].isspace()
    value = 0.0
    if (not history or prev == '<|endoftext|>') and token == '//\n':
        value = -5.9
    elif '\\\n' in token:
        value = -2.5
    elif '\\"' in token:
        value = 0.24
    elif word == 'assistant' and prev == '<|im_start|>':
        value = -0.576
    elif boundary:
        if word == 'only':
            value = -0.70 if prev == 'the' else 0.04
        elif word in {'necessary', 'required', 'respective'} and prev == 'the':
            value = 1.5
        elif word == 'to':
            if prev in {'way', 'ways'}:
                value = (-0.35 if last_value > 0 else
                         max(-3.4, -1.0 + 0.45 * last_value))
            elif prev == 'opportunities':
                value = -2.5
            elif prev in {'place', 'places'}:
                value = -0.3 + last_value
            elif prev in {'opportunity', 'opportunities', 'chance', 'chances',
                          'reason', 'reasons'}:
                value = -0.4 + 0.8 * last_value
            elif prev in {'time', 'need', 'answer', 'ability'}:
                value = min(0.0, 0.5 * last_value)
        else:
            value = noun_value(word, history, previous)
    return (doc, (history + [word])[-4:], token, value), float(value)

programs.haiku:
"""Component layers.1.mlp.down_proj:3022 as a readable rule.

What it does: a negative response to head nouns that usually take an infinitive "to" next:
"the best WAY to", "a great PLACE to", "the first TIME ...", "no REASON to", "an OPPORTUNITY to".
It is strongest on "way" when a superlative or strong evaluative word ("only", "best",
"easiest", "great", "better") comes just before it, weaker after "a/an/one/another", weaker
still after "any/some/other/new", and near zero after "the", "this", "its", "their".
The "to" right after such a noun gets about 0.9 times the noun's own value. Two smaller fixed
effects are included: the "assistant" tag that opens a chat turn, and a backslash line
continuation in code.
"""

READS = ()

# How strongly each head noun responds (1 = "way", the strongest and most common case).
HEAD_NOUNS = {" way": 1.0, " ways": 1.0, " opportunity": 0.5, " chance": 0.5, " reason": 0.6,
              " reasons": 0.6, " place": 0.4, " time": 0.3, " times": 0.3}

# Words just before the noun and how much they strengthen it.
MODIFIER = {}
for w in [" only", " best", " better", " great", " good", " easy", " perfect", " right", " first",
          " last", " next", " single", " no"]:
    MODIFIER[w] = 3.5
for w in [" a", " an", " one", " another"]:
    MODIFIER[w] = 1.8
for w in [" any", " some", " every", " other", " different", " new", " same"]:
    MODIFIER[w] = 0.6


def modifier_strength(word):
    if word in MODIFIER:
        return MODIFIER[word]
    if word.endswith("est"):  # superlatives: easiest, fastest, simplest, ...
        return 3.5
    return 0.0


def noun_value(toks, i):
    """Activation for the head noun at index i, from the two words before it."""
    strength = max((modifier_strength(w) for w in toks[max(0, i - 2):i]), default=0.0)
    return -HEAD_NOUNS[toks[i]] * max(strength, 0.3)


def step(carry, prefix, upstream):
    toks = prefix.token_strings
    i = len(toks) - 1
    cur = toks[i]
    if cur in HEAD_NOUNS:
        return None, noun_value(toks, i)
    if cur == " to" and i >= 1 and toks[i - 1] in HEAD_NOUNS:
        return None, 0.9 * noun_value(toks, i - 1)
    if cur == "assistant" and i >= 1 and toks[i - 1] == "<|im_start|>":
        return None, -0.55
    if cur == " \\\n":
        return None, -2.5
    return None, 0.0

programs.sol:
r"""A document-start dip, with a few sparse literal-text pulses.

The dip depends coarsely on the first token's writing style: unspaced
ASCII-letter words are more negative, numbers less negative. Most later tokens
are near zero. Exceptions detected here are TeX's \cr, escaped backslashes,
and a handful of distinctive document openings seen in the training data.
This is a surface-pattern approximation, not a single semantic category.
"""
READS = ()


def opening_value(token):
    word = token.strip()
    if token == 'Hand':
        return 1.02
    if token == 'void':
        return 0.88
    if token == '(function':
        return 0.12
    if token == '<|im_start|>':
        return -1.04
    if word.isdigit():
        return -0.38
    if word.isascii() and word.isalpha():
        if token.startswith(' '):
            return -0.53
        return -0.56 if word.isupper() else -0.79
    if word.isalpha():
        return -0.54
    if word.isascii() and any(c.isalpha() for c in word):
        return -0.78
    return -0.60


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        position, previous = 0, ''
    else:
        _, position, previous = carry
        position += 1
    token = prefix.token_strings[-1]
    value = opening_value(token) if position == 0 else 0.0
    if position == 1:
        if previous == 'Hy' and token == 'dro':
            value = 3.08  # the initial Hydro- prefix
        elif previous == '{' and token == '[':
            value = 1.55  # opening template brackets
        elif previous == '(function' and token == ' ()':
            value = 2.40  # an anonymous function's empty arguments
    if position > 0:
        if token == 'cr' and previous.endswith('\\'):
            value = 1.02
        elif token == '\\\\':
            value = -0.22
        elif token == ' \\\\':
            value = 0.20
    return (doc, position, token), value

"""Approximate positive d-fragment responses, leaving other positions at zero.

Short Arabic dal fragments fire most when they finish a recognizable Arabic
word; word frequency distinguishes such completions from unfinished stems.
Arabic perfect markers and romanized h-m-d names are handled separately.
A smaller response covers capitalized h/j/q-vowel-d name fragments. This
conservative approximation does not attempt the component's negative tail.
"""
import re
from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()
HAMD_PATTERN = (
    r'(?:m[auo]h[ae]?mm?[ae]?d|[ae]hm[ae]d|m[ae]hm[ou]+d)'
)

@lru_cache(maxsize=20000)
def arabic_frequency(word):
    return zipf_frequency(word, 'ar')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    word, previous = ('', '') if carry is None or carry[0] != doc else carry[1:]
    token = prefix.token_strings[-1]
    for char in token:
        word = (word + char)[-60:] if char.isalpha() else ''
    low = word.lower()
    value = 0.0
    marker = token.strip()
    if marker in ('قد', 'وقد', 'فقد'):
        value = 2.0 if marker == 'قد' else 3.4
    elif 'د' in token and not token[:1].isspace():
        if any('\u0600' <= c <= '\u06ff' for c in previous):
            frequency = arabic_frequency(word)
            if len(token) > 2:
                value = 0.65
            elif frequency > 3.5:
                value = 2.0 if len(word) <= 6 else 3.2
            elif len(word) > 4:
                value = 1.8 if frequency > 1.5 else 0.8
            else:
                value = 0.65 if token.endswith('ده') else 0.2
    elif re.fullmatch(HAMD_PATTERN, low):
        value = 0.9
    elif word.istitle() and len(token) <= 2 and token.islower():
        if previous[-1:].isalpha() and re.search(r'[hjq][aiu]+d$', low):
            value = 0.8
    return (doc, word, token), value

programs.haiku:
"""Arabic dal (د) fragments: fires on mid-word pieces of Arabic-script words that contain
the letter dal (د), more so when the previous piece is also mid-word Arabic (deep inside a
word). Whole-word tokens (leading space) containing dal get a small value. Everything else
is 0."""

READS = ()

DAL = "د"
ARABIC_LO, ARABIC_HI = "؀", "ۿ"


def _is_arabic(text):
    return any(ARABIC_LO <= ch <= ARABIC_HI for ch in text)


def _mid_word_arabic(text):
    # A piece of an Arabic word: Arabic script and no leading space.
    return _is_arabic(text) and not text.startswith(" ")


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    value = 0.0
    if DAL in token:
        if _mid_word_arabic(token):
            value = 1.2
            same_doc = len(prefix.token_strings) > 1 and (
                prefix.document_ids[-2] == prefix.document_ids[-1]
            )
            if same_doc and _mid_word_arabic(prefix.token_strings[-2]):
                value += 0.8
        else:
            value = 0.3
    return carry, float(value)

programs.sol:
"""An opening-token bias, rather than a sustained topic detector.

Use grammatical word classes and token shape to approximate the large values
at a document's opening. Keep that value through an initial run of identical
tokens; after a different token supplies context, predict zero. The lexical
rules are approximations: unrelated opening words still vary considerably.
"""

READS = ()


def opening_value(text):
    word = text.strip()
    lower = word.lower()
    capital = word[:1].isupper()
    spaced = text.startswith(' ')

    # Layout and programming-language opening markers.
    if text == '#':  # Markdown heading / preprocessor marker.
        return 0.58
    if text == ' (':
        return 0.55
    if text == '//\n':
        return 10.26
    if text == '\r':
        return 8.27
    if text.startswith('<|') and text.endswith('|>'):
        return 0.54
    if not word:
        return -0.55 if '\n' not in text else 0.0
    if text.startswith('{'):
        return -7.0 if len(text) > 1 else -2.1
    if lower in {'#ifndef', '#ifdef', '#define'}:
        return -4.0
    if word == '··':
        return -3.63

    # Relational words, articles, and quantification.
    if lower == 'of':
        return -5.35
    if lower in {'de', 'di', 'del', 'des', 'della', 'da'}:
        return -2.5 if not capital else -1.8
    if lower in {'el', 'le', 'la'}:
        return -2.3
    if word == 'ال':  # Arabic definite article.
        return -8.46
    if lower == 'and' or word in {'和', '与'}:
        return -2.45 if lower == 'and' else -4.8
    if lower in {'each', 'every'}:
        return -4.3 - 1.3 * (lower == 'every') - 1.2 * capital
    if lower == 'total':
        return -7.9
    if lower in {'some', 'many', 'much', 'several'}:
        return -3.8
    if lower in {'both', 'other'}:
        return 2.0
    if lower in {'at', 'about', 'regarding'}:
        return -3.1 if lower == 'at' else -3.9
    if lower == 'the':
        return -2.6 if word.isupper() else (0.2 if capital else -1.0)
    if lower in {'a', 'an'}:
        return 0.2 if lower == 'a' else -2.0

    # Negation and a few especially asymmetric grammatical forms.
    if lower == 'not':
        return 5.23 if spaced and not capital else 3.3
    if lower in {'cannot', 'never'}:
        return 2.5
    if lower == 'it':
        return 0.5 if capital else (3.1 if spaced else 1.8)
    if lower == 'is':
        return -0.8 if spaced and not capital else -5.5
    if lower in {'have', 'has', 'had', 'do', 'does', 'did'}:
        return -1.6
    if lower == 'your':
        return -2.4
    if lower in {'i', 'we', 'you', 'he', 'she', 'they', 'me', 'us', 'them'}:
        return 0.3 if capital else -0.3
    if lower in {'can', 'could'}:
        return 2.0 if spaced and not capital else -0.2
    if lower in {'class', 'struct', 'enum', 'interface'} and not capital:
        return -2.5 if spaced else -4.0

    # Broad orthographic defaults, not a vocabulary lookup.
    if word.isnumeric():
        return -0.3
    if not any(c.isalpha() for c in word):
        return -0.35
    value = -0.55 + 0.10 * min(len(word), 12) - 0.5 * capital
    value += 1.1 * word.startswith('_')
    value += 1.0 * (word.startswith('.') and len(word) > 1)
    value += 0.8 * (len(word) > 3 and lower.endswith('s'))
    value += 1.0 * (len(word) > 3 and lower.endswith('ed'))
    value -= 0.6 * (len(word) > 4 and lower.endswith('ing'))
    return value


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    token = prefix.token_ids[-1]
    if carry is None or carry[0] != document:
        value = opening_value(prefix.token_strings[-1])
        carry = (document, token, value, True)
    else:
        doc, first_token, value, opening_run = carry
        opening_run = opening_run and token == first_token
        carry = (doc, first_token, value, opening_run)
    return carry, carry[2] if carry[3] else 0.0

"""Partial spelling rules for an early MLP component.

Selected vowel-initial fragments receive a negative bias, stronger after
short i/e syllables or consonant-only fragments. Lua and the Chinese
Luo/king/dragon characters receive positive values. Split Thai เพื่/เพื่อ
is negative. Hu+am is positive (the common transposition in Huamn).
Document openings have separate biases, including a sharp negative response
to the opening number 12. All other positions return zero.

These are spelling-specific responses, not a general semantic detector.
The rules cover only part of the component's activation variance.
"""
READS = ()

# Relational -ian; Latin/Romance -io, -ius; participial -ante, -iant;
# and the Greek name element -ander ("man").
ENDING_BIAS = {
    'ian': -0.33,
    'io': -0.24,
    'ius': 0.0,
    'ante': -0.16,
    'iant': -0.62,
    'ander': 0.0,
    'iot': -0.15,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        count, previous, beginning = 0, '', ''
    else:
        _, count, previous, beginning = carry
    ending = token.lower()
    if ending in {'ians', 'iana', 'iance'}:
        ending = 'ian'
    value = ENDING_BIAS.get(ending, 0.0)
    if ending in ENDING_BIAS:
        syllable = previous.strip().lower()
        vowels = [ch for ch in syllable if ch in 'aeiou']
        if (syllable.isascii() and syllable.isalpha()
                and len(syllable) <= 5 and len(vowels) <= 1
                and (len(syllable) == 1 or syllable[0] not in 'aeiou')):
            vowel = vowels[0] if vowels else ''
            if vowel == 'i':
                value -= 1.2 if ending == 'ian' else (
                    1.8 if ending in {'io', 'ius'} else 0.6)
            elif vowel == 'e':
                value -= 0.2 if ending == 'ian' else (
                    1.2 if ending in {'ante', 'iant', 'ander', 'iot'} else 0.0)
            elif not vowel:
                value -= 0.45 if ending == 'ian' else 0.15

    if token.strip().lower() == 'lua':
        value = 3.8             # Lua language/name spelling
    elif token.lower() == '.lua':
        value = 1.9             # Lua source-file extension

    character = token
    if '\ufffd' in token or token in {'ื่', 'อ'}:
        recent = b''.join(prefix.token_bytes[-min(count + 1, 3):])
        decoded = recent.decode('utf-8', 'ignore')
        if decoded and recent.endswith(decoded[-1].encode('utf-8')):
            character = decoded[-1]
        if token == 'ื่' and decoded.endswith('เพื่'):
            value = -3.8
        elif token == 'อ' and decoded.endswith('เพื่อ'):
            value = -3.5

    if character in {'罗', '羅'}:       # Luo: surname/transcription character
        value = 4.0
    elif character == '王':            # king, also the surname Wang
        value = 1.3
    elif character in {'龙', '龍'}:    # dragon
        value = 1.9
    if count == 0:
        value = -0.18
        if token.lower() in {'a', 'an', 'the'}:
            value = -0.80
        elif token.lower() in {'he', 'she', 'it', 'we', 'they', 'i', 'you'}:
            value = -0.65
        elif token.lower() in {'this', 'that', 'these', 'those'}:
            value = -0.75
        elif token == '<|im_start|>':
            value = -0.58
        elif token == '<|endoftext|>':
            value = 4.23
    if count == 1 and beginning == '1' and token == '2':
        value = -4.23
    elif count == 2 and beginning == '12' and token == '2':
        value = -1.59
    elif previous.strip() == 'Hu' and token == 'am':
        value = 0.96
    beginning = (beginning + token) if count < 2 else beginning
    return (doc, count + 1, token, beginning), value

programs.haiku:
"""Layer-1 MLP down_proj component 3028: a sparse, mostly token-driven feature.

What it responds to (from ~2M training tokens):
- Start of a document: a small negative offset (about -0.25 on average).
- The Chinese character 罗/羅 (surname "Luo", as in 罗曼蒂, 罗伯特): strongly positive (about +4).
- A few other surname characters, 龙/龍, 王, 黄/黃, 황, 卢, 廖: moderately positive (about +1.2).
  The Korean surname 안 is negative (about -1.4). Most other surnames are near zero.
- Latin-script name fragments that continue a split word (sim|ian, Vi|ola, min|io, Ne|ander,
  Liv|onian): mildly negative (about -0.3 on average, with large spread).
- The piece "am" right after "Hu" (Hu|am|n, "Human"): positive (about +1).
Everything else is 0.
"""

READS = ()

LUO = {"罗", "羅"}
NAME_CHARS = {"龙", "龍", "王", "黃", "黄", "황", "卢", "廖"}
KOREAN_AN = {"안"}
NAME_PIECES = {"ian", "io", "ola", "ante", "anth", "iant", "ander", "ilio", "ius", "onian"}


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    prev = prefix.token_strings[-2] if prefix.position > 0 else ""
    if prefix.position == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        return None, -0.25
    if tok in LUO:
        return None, 4.0
    if tok in NAME_CHARS:
        return None, 1.2
    if tok in KOREAN_AN:
        return None, -1.4
    if prev == " Hu" and tok == "am":
        return None, 1.0
    if tok in NAME_PIECES and not prev.startswith(" "):
        return None, -0.3
    return None, 0.0

programs.sol:
"""Local phrase and spelling responses.

The largest phrase signals are positive on the article in 'such a/an',
and negative on 'that' after 'such' or 'way'. There are also signed
responses to several ch- spelling families, including musical chords and
Unix ch- commands. Split spellings are recognized as they are completed;
no future text is used. Unrecognized text contributes zero.
"""
import re

READS = ()


def spelling(word):
    if word.startswith(('chmod', 'chown', 'chdir')):
        return 7.0
    if word in ('chord', 'chords'):
        return 3.4
    if word.startswith('chelat'):
        return -2.3
    if word.startswith('charit'):
        return -4.0
    if word.startswith(('chase', 'chasi')):
        return -4.5
    if word.startswith('chat'):
        return -2.3
    if word.startswith('chocol'):
        return -2.6
    if word.startswith('christmas'):
        return -1.9
    if word.startswith('charl'):
        return -1.7
    if word.startswith(('cheryl', 'chloe')):
        return -2.5
    if word.startswith(('chapel', 'chester', 'chuck')):
        return -1.3
    return 0.0


def continuation(ending):
    if ending.startswith(('el', 'et', 'at', 'al', 'ari', 'arl')):
        return -2.3
    if ending.startswith(('ap', 'il', 'it', 'lo', 'lag', 'anc', 'ant')):
        return -0.8
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        previous, tail = '', ''
    else:
        _, previous, tail = carry
    lower = token.lower()
    value = 0.0
    if lower in (' a', ' an'):
        if previous.strip().lower() == 'such':
            value = 7.8 if previous.strip() == 'Such' else 6.8
        elif previous.strip().lower() == 'quite':
            value = 1.8
    elif lower == ' that':
        if previous.strip().lower() == 'such':
            value = -5.0
        elif previous == ' way':
            value = -2.6
        elif previous in (' so', 'so'):
            value = -0.6

    # Only the newest word fragment is retained, not the full document.
    match = re.search(r'[a-z]+\Z', tail + lower)
    word = match.group() if match else ''
    now, before = spelling(word), spelling(tail)
    split = (lower[:1].isalpha() and 'ch' in tail
             and (len(tail) <= 5 or previous.lower().endswith('ch')))
    if now and not before:
        value = now * (1.6 if split else 1.0)
    elif split and not now:
        # Fire when a new first-syllable spelling becomes recognizable,
        # not on every later suffix of the same word.
        ending = word.rsplit('ch', 1)[-1]
        old_ending = tail.rsplit('ch', 1)[-1]
        new_group = continuation(ending)
        if new_group != continuation(old_ending):
            value = new_group
    if lower.startswith('.chdir'):
        value = 1.3
    return (doc, token, word[-24:]), value

"""Approximate the component as a -lar/-ular spelling-family detector.

Short suffix pieces are strongest. A split -ar is boosted by recent l
in the unfinished word. Whole words are weaker: English frequency,
length, and adjective readings moderate them; angular compounds are
stronger. Related endings and Romance -mente are also recognized.
Normalize/transliterate spelling and reset the word at document changes.
"""
import re
import unicodedata
from anyascii import anyascii
from functools import lru_cache
from wordfreq import zipf_frequency
import wordnet

READS = ()


@lru_cache(maxsize=32768)
def latin(text):
    # Arabic alif writes the vowel that ASCII transliteration omits.
    text = text.translate(str.maketrans("اأإآ", "aaaa"))
    return anyascii(unicodedata.normalize('NFKD', text)).lower()


@lru_cache(maxsize=16384)
def whole_word(word):
    """Common complete words have a weaker suffix cue than short fragments."""
    base = word.rstrip('s')
    derived_noun = base.endswith('ity')
    if derived_noun:
        base = base[:-3]
    if base.endswith('ly'):
        base = base[:-2]
    pos = wordnet.parts_of_speech(base)
    if pos and 'adjective' not in pos:
        return 0.1
    if base.endswith('angular'):
        return 3.0
    if zipf_frequency(base, 'en') >= 4.8:
        return 0.6 if derived_noun else 1.0
    return max(0.7, 4.5 - 0.3 * len(word))


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '')
    s = latin(prefix.token_strings[-1])
    continuation = bool(s and s[0].isalpha())
    stem = carry[1] if continuation else ''
    word = re.split('[^a-z]', stem + s)[-1][-40:]
    piece = s.strip()
    value = 0.0
    if piece == 'ular':
        value = 4.9
    elif piece in ('olar', 'icular', 'ilar', 'ellar', 'iliar', 'lyar'):
        value = 3.7
    elif piece == 'lar':
        value = 2.5
    elif piece in ('alar', 'uler'):
        value = 1.6
    elif re.fullmatch('lar[aiou].*', piece):
        value = 1.3
    elif piece == 'mente' and stem.endswith('lar'):
        value = 3.0
    elif re.match(r'^[^aeiou]l(?:a|ai)r', piece):
        value = 0.2
    elif re.search(r'lar(?:ly|ity|ities|s)?$', piece):
        value = whole_word(piece)
    elif re.search(r'l[a-z]{0,4}ar(?:y|ily|ly|ity|ities|s)?$', piece):
        value = 0.8
    elif piece == 'ler':
        value = 0.2
    elif continuation:
        m = re.search(
            r'(?:ar|air|ier|er|ir)'
            r'(?:e|i|y|ia|ius|ios|ies|ity|ities|ly|s|es|en|em|ern)?$',
            piece,
        )
        if m:
            before = (stem + piece[:m.start()])[-7:]
            if m.group(0).startswith('ier'):
                value = 2.5 if 'l' in before else 0.0
            elif m.group(0).startswith(('er', 'ir')):
                value = 0.25 if before.endswith('l') else 0.0
            elif before.endswith('l'):
                value = 4.0 if not piece.endswith('y') else 0.7
            elif 'l' in before:
                value = 1.2 if not piece.endswith('y') else 0.5
    return (doc, word), value

"""A spelling-based approximation to a negative -ic-family suffix response.

Recognize word-internal -ic/-ik/-ique/-isch and cognate Slavic, Greek,
and Japanese loanword spellings, including endings split across tokens.
Longer stems strengthen some responses. Everything else is near zero.
Only the unfinished word is retained; document boundaries reset it.
This does not attempt to explain unrelated, vocabulary-specific variation.
"""
import re
import unicodedata

READS = ()
SCALE = 1.0
WORD_TAIL = re.compile(r'[^\W\d_]+$')
LATIN_ENDING = re.compile(
    r'^(?:[aeiou](?:s|n|m)?|[ao]n[aois]?|al(?:e|s|es|ly)?|'
    r'ale[sm]?|amente|um|ov|ova)$')
RUSSIAN_ENDING = re.compile(r'^(?:[аеуыи]|ам[и]?|ов[аы]?|ой|е[йм]|ах|у|ом)$')
ADJECTIVE = re.compile(
    r'^(?:н|енн)(?:ый|ая|ое|ые|ого|ой|ых|ым|ыми|ую|ом|ому)$')
GREEK_TAIL = re.compile(r'ικ[αάεέηήοόωώυύιίς]*$')
# Alternative spellings of the suffix, not a list of words or token IDs.
SPELLINGS = (
    ('ik', .51), ('ikk', .49),
    ('ich', .21), ('iche', .52),
    ('iqu', .51), ('isch', 1.17), ('isk', .17),
    ('ycz', 2.16), ('icz', .68),
)


def response(s, word):
    if not s.isalpha():
        return .002
    if not word:
        return .007
    s = unicodedata.normalize('NFKC', s).lower()
    word = unicodedata.normalize('NFKC', word).lower()
    value = -.001

    # Latin and Germanic -ic, its inflections, and boundaries inside it.
    latin_ic = s.startswith('ic') and not s.startswith(('ich', 'ick'))
    if latin_ic:
        value -= .09 if s == 'ic' else .19 if s.startswith('ical') else .37
    for spelling, strength in SPELLINGS:
        if s.startswith(spelling):
            value -= strength
    if latin_ic or s.startswith(('ik', 'isk', 'iqu')):
        value -= .18 * (len(word) >= 4) + .20 * (len(word) >= 7)
    if word.endswith(('ic', 'ik', 'ick')):
        if LATIN_ENDING.fullmatch(s):
            value -= .78 + .68 * word.endswith('ic')
            if s in ('al', 'ale', 'ally', 'as', 'o', 'a', 'i', 'um'):
                value -= .70
        if s in ('s', 'he', 'orum', 'osa', 'ul'):
            value -= 1.52
    if word.endswith(('i', 'y', 'í')) and s.startswith(('c', 'k', 'č')):
        value -= .43
    if ((word.endswith(('ic', 'yc')) and s.startswith('z'))
            or (word.endswith(('y', 'i')) and s.startswith('cz'))):
        value -= 2.74
    if word.endswith(('is', 'ys')) and s.startswith('ch'):
        value -= .66
    if word.endswith(('ick', 'sk', 'ik')) and re.fullmatch(
            r'(?:ý|é|á|í|ého|ému|ých|ými|ým|ou)', s):
        value -= 1.31

    # Cyrillic -ик/-ич/-ическ/-ск and adjectival or case endings.
    cyrillic_ic = s.startswith(('ик', 'ич'))
    split_ic = word.endswith(('и', 'ы')) and s.startswith(('к', 'ч'))
    if cyrillic_ic:
        value -= .30 + .39 * s.startswith('ичес')
    if split_ic:
        value -= .85 + .06 * s.startswith('ч')
    if cyrillic_ic or split_ic:
        value -= .69 * (len(word) >= 4) + .36 * (len(word) >= 7)
    if s.startswith('ск'):
        value -= .74
    if word.endswith('ичес') and s.startswith('к'):
        value -= 1.07
    if word.endswith('ич') and s.startswith(('ес', 'еств')):
        value -= 1.38
    if word.endswith('ическ'):
        value -= 1.61
    if (word.endswith('ик') and not word.endswith(('ник', 'щик'))
            and RUSSIAN_ENDING.fullmatch(s)):
        value -= 1.74
    if word.endswith(('ски', 'цки', 'ьки')) and s in ('х', 'м', 'й', 'е'):
        value -= 1.84
    if ADJECTIVE.fullmatch(s):
        value -= .32
    if s.startswith('альн'):
        value -= .45

    # Greek -ικ- and Japanese -ック in loans such as "music".
    if s.startswith('κ') and word.endswith(('ι', 'ί')):
        value -= 1.32
    if GREEK_TAIL.search(word) and re.fullmatch(r'[αάεέηήοόωώυύιίς]+', s):
        value -= 4.59 - 1.26 * (len(word) < 4)
        if word.endswith(('ύ', 'υ')) and s == 'ς':
            value += 1.36
    if s.startswith('ック') and word[-1] in 'イシジチニヒビピミリィ':
        value -= 2.32
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    word = carry[1] if carry is not None and carry[0] == doc else ''
    s = prefix.token_strings[-1]
    value = SCALE * response(s, word)
    tail = WORD_TAIL.search(s)
    word = ((word if s.isalpha() else '') + tail.group())[-48:] if tail else ''
    return (doc, word), value

"""A spelling-fragment approximation, not a semantic word classifier.

Positive responses mark Christ/Chris/crystal-like fragments. Negative responses
mark drill/grill and short r-to-l continuations. Transliteration shares these
rules across alphabets. Other tokens get zero; documents reset the context.
"""
import re
from anyascii import anyascii

READS = ()
STEMS = {'chris': 2.1, 'crystal': 2.6, 'crystals': 1.5, 'crystall': 1.3}


def predict(previous, current):
    p = anyascii(previous).lower().rstrip("'")
    t = anyascii(current).lower().rstrip("'")
    word = t.strip()
    if re.fullmatch(r'(?:ch|kh|[chk])?rist', word):
        joins = t[0].isalpha() and re.search(r'(?:ch|kh|[chk])$', p)
        return 7.1 if joins else 4.9
    if word in STEMS:
        return STEMS[word]
    if re.fullmatch(r'[bdgt]rill(?:ed|s|ing)?', word):
        return -4.6
    if word == 'ril':
        return -4.5
    if not p or not t or not t[0].isalpha():
        return 0.0
    if re.search(r'r[iey]st$', p) and re.fullmatch(r'[aioyu]', t):
        return 7.0 if t == 'i' else 3.9
    if re.search(r'r$', p) and re.fullmatch(r'ill?[a-z]{0,3}', t):
        return -5.6 if t.startswith('ill') or t == 'il' else -2.2
    if re.search(r'r$', p) and re.fullmatch(r'ull?[a-z]{0,2}', t):
        return -1.7
    if re.search(r'r[aeiouy]$', p) and re.fullmatch(r'[aeiouy]?ll?[a-z]{0,2}', t):
        return -3.2 if p.endswith('ry') else -0.6
    if re.search(r'(?:ch|kh|[ck])r$', p) and re.match(r'[iey][sz]', t):
        return 10.0 if t in ('ist', 'yst') else 2.2
    if re.search(r'(?:ch|kh|[ck])$', p) and re.match(r'ri[sz]', t):
        return 3.3
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    return (doc, token), predict(previous, token)

"""Doubled vowels, especially 'ee', in short word fragments.

A new 'ee' spanning two tokens is strongest.  An 'ee' inside a token is
weaker in common, long words, and can linger as the same word continues.
Accents are folded away. Other doubled vowels, Cyrillic double-e, and the
Japanese vowel-length mark have small positive responses. Document starts
receive a small negative baseline. Word frequency is an English corpus
frequency, not a table of fitted token identities.
"""
import re
import unicodedata
from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()

@lru_cache(maxsize=32768)
def plain(text):
    return ''.join(c for c in unicodedata.normalize('NFD', text.lower())
                   if not unicodedata.combining(c))

@lru_cache(maxsize=32768)
def frequency(word):
    return zipf_frequency(word, 'en') if word else 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    previous = '' if first else carry[1]
    token = prefix.token_strings[-1]
    continued = bool(previous and token[:1].isalpha())
    joined = previous + token if continued else token
    old = plain(previous) if continued else ''
    text = plain(joined)
    current = plain(token)
    match = re.search(r'[^\W\d_]+$', joined)
    word = match.group()[-50:] if match else ''
    state = (doc, word)
    size = len(token.strip())
    length = len(word)
    new_ee = text.count('ee') > old.count('ee')
    cross_ee = old.endswith('e') and current.startswith('e')

    if cross_ee:
        if size <= 2:
            value = 3.25 if length <= 6 else 1.85
        else:
            value = 2.30 if length <= 6 else (1.30 if length <= 8 else 0.20)
    elif first:
        value = -0.15
    elif new_ee:
        freq = frequency(word)
        if size <= 3:
            if token.strip().isupper():
                value = 3.44
            elif freq <= 4.9:
                value = 1.95 if frequency(token.strip()) > 3.0 else 0.46
            else:
                value = 0.61 if token.strip()[:1].isupper() else 0.32
        elif freq <= 4.7:
            if size <= 4:
                value = 1.10
            else:
                value = 0.46 if length <= 6 else 0.10
        elif freq <= 5.5:
            value = 0.59 if length <= 4 else 0.094
        else:
            value = 0.03
    elif 'ee' in old:
        tail = len(text) - text.rfind('ee') - 2
        if len(previous) <= 3:
            value = 2.85
        else:
            value = 0.75 if tail <= 3 else (0.18 if tail == 4 else 0.0)
    else:
        value = 0.0
        for pair, response in [('ее', 0.19), ('oo', 0.065), ('aa', 0.32),
                               ('ii', 0.11), ('uu', 0.17)]:
            if text.count(pair) > old.count(pair):
                value = max(value, response)
        if old.endswith('o') and current.startswith('o'):
            value = 0.28
        if 'ー' in token:
            value = max(value, 0.16)
    return state, value

"""A sparse approximation of code/data and quotation boundaries.

Training showed large responses at these boundaries. Most tokens get zero.
Field separators and value-opening quotes usually get negative predictions,
scaled by the preceding name's character length and number of token pieces.
Assigned/object-field function literals and speech-introducing colons are
positive. A few rules cover imports, pipes, and continuing middle-dot leaders.
This is not a full parser: state only remembers recent tokens, contiguous name
lengths, closed names, and the most recent assignment/key boundary. It resets
at document changes and leaves most small lexical variation unmodeled.
"""
import re

READS = ()
NAME = re.compile(r'[\w./@-]+$')
SOURCE_FILE = re.compile(
    r'\.(?:c|h|cc|cpp|hpp|py|rs|go|java|js|ts|tsx|jsx|php|rb|swift)$'
)
REPORTING = {'said', 'says', 'say', 'wrote', 'writes', 'asked', 'replied'}
KEY_ENDS = {'":', "':", '":"', "':'", ':"', ":'"}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', '', 0, 0, 0, 0, 0, 0)
    (_, previous, before_previous, pieces, closed_pieces, key_pieces,
     chars, closed_chars, key_chars) = carry
    token = prefix.token_strings[-1]
    s, p = token.strip(), previous.strip()
    run_pieces, run_chars = pieces, chars
    if not pieces and (not p or p[-1:] in ('"', "'", ']', ')', '`')):
        pieces, chars = closed_pieces, closed_chars
    width = min(chars, 60)
    key_width = min(key_chars, 60)
    extra = min(max(pieces - 1, 0), 8)
    key_extra = min(max(key_pieces - 1, 0), 8)
    value = 0.0

    if s and set(s) == {'·'} and p and set(p) == {'·'}:
        value = 2.67  # Continuing middle-dot leaders.
    elif s in ('=function', ':function'):
        value = 2.8
    elif s == 'function':
        if p == '=' or (p == 'async' and before_previous.strip() == '='):
            value = min(6.0, 2.2 - 0.14 * key_extra + 0.16 * key_width)
        elif p == ':':
            value = 2.25
    elif s == 'func' and p in ('=', ':'):
        value = 0.6
    elif s == 'async' and p == '=':
        value = 1.2
    elif s == 'from' and p == '}':
        value = -1.0  # JavaScript named-import boundary.
    elif s in ('":', "':"):
        value = -0.16 * extra - 0.028 * width
    elif s in ('":"', "':'"):
        value = -0.93 - 0.26 * extra - 0.025 * width
    elif s in (':"', ":'"):
        value = (-0.7 + 0.3 * extra - 0.125 * width
                 if p and p[0].isupper() else 0.3)
    elif s in ('="', "='"):
        value = 0.08 - 0.08 * extra - 0.025 * width
    elif s in (']:', '**:'):
        value = -0.5
    elif s == ':':
        if p in REPORTING:
            value = 1.0 if '\n' in token else 2.4
        elif '\n' in token:
            value = 0.03
        elif SOURCE_FILE.fullmatch(p):
            value = -0.8
        else:
            value = 0.06 - 0.01 * extra - 0.01 * width
    elif s == '=>':
        if p in ('"', "'") or (not p and closed_pieces):
            value = -1.8 - 0.2 * min(max(closed_pieces - 1, 0), 8)
        elif p.endswith(')') and '(' not in p:
            value = -0.54
        else:
            value = 0.04 - 0.19 * extra
    elif s in ('|', '||'):
        value = -0.06
        if not p:
            value -= 0.045 * min(len(previous), 32)
        elif p.endswith(('"', "'")):
            value = -0.65
    elif s == '=':
        if p.startswith('.') or p.endswith(']'):
            value = -0.15
    elif token in (' "', " '"):
        if p in KEY_ENDS:
            value = 0.18 - 0.3 * key_extra - 0.047 * key_width
        elif p == '=>':
            value = -1.5 - 0.2 * key_extra
        elif p == '=':
            value = -0.03 - 0.03 * key_extra - 0.023 * key_width
        elif p == ':':
            value = 0.23 + 0.09 * key_extra - 0.07 * key_width
            if before_previous.strip() in REPORTING:
                value = 1.0
        elif p == 'COMMENT':
            value = -1.15
    elif token == ' (' and p in (':', '='):
        value = 0.25
    elif token == ' .' and p in (':', '='):
        value = 0.45

    # Preserve name lengths across closing quotes/brackets, for the next boundary.
    if NAME.fullmatch(token):
        pieces = run_pieces + 1
        chars = run_chars + len(token)
        closed_pieces = closed_chars = 0
    elif s and NAME.fullmatch(s):
        pieces = 1
        chars = len(s)
        closed_pieces = closed_chars = 0
    else:
        if s and s[-1] in ('"', "'", ']', ')', '`') and pieces:
            closed_pieces, closed_chars = pieces, chars
        if s in ('=', ':') or s in KEY_ENDS:
            key_pieces, key_chars = pieces, chars
        elif s == '=>':
            key_pieces, key_chars = closed_pieces, closed_chars
        pieces = chars = 0
    value = max(-3.5, min(6.0, value))
    state = (doc, token, previous, pieces, closed_pieces, key_pieces,
             chars, closed_chars, key_chars)
    return state, float(value)

programs.haiku:
"""Draft F: function-expression starts (+), speech colons (+), and key-value separators in data literals (-)."""
READS = ()
SPEECH_VERBS = {"said", "says", "asked", "replied", "wrote", "added", "explained"}
SOURCE_SUFFIXES = (".go", ".py", ".php", ".rs", ".java", ".ts", ".js", ".c", ".cpp", ".rb")


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    prev = prefix.token_strings[-2].strip() if len(prefix) > 1 else ""
    value = 0.0
    if tok == "··":
        value = 2.7
    elif tok.strip() == "function" and prev in ("=", ":", "async"):
        value = 3.8
    elif tok in ("=function", ":function"):
        value = 3.0
    elif tok == ":" and prev in SPEECH_VERBS:
        value = 2.9
    elif tok == ":" and prev.endswith(SOURCE_SUFFIXES):
        value = -0.9
    elif tok in (" =>", "=>"):
