programs.sol:
"""Mostly negative responses to short cop/copy/kop spellings and their joins.

This is a subword spelling heuristic, not a general detector of duplication.
It continues through copy-word endings and 'copy of', using transliteration
for other scripts. Smaller rules cover cp, cup and backup spellings. Two
separate cues are Vietnamese cả (positive) and document-opening Title:
(negative). Split Chinese copy verbs have a separate rule. Weak,
unmodeled activity is predicted as zero.
"""
import re
from functools import lru_cache
from anyascii import anyascii

READS = ()
COPY_FORMS = {'copied': -3.5, 'copies': -4.3, 'copying': -2.2}


@lru_cache(maxsize=20000)
def roman(text):
    return anyascii(text).lower()


def response(previous, current, position, tail):
    s = roman(current)
    word = s.lstrip(' \t\r\n._-')
    if current.lower().strip() == 'cả':
        return 5.6
    if current == 'ả':
        if tail.endswith('c'):
            return 10.0
        return 3.8 if tail.endswith('ch') else 0.0
    if position == 1 and previous == 'Title' and current == ':':
        return -11.5
    if (previous.endswith('拷') and current.startswith(('贝', '貝'))
            or previous.endswith(('複', '复')) and current.startswith(('製', '制'))):
        return -7.0

    # A following preposition or word ending continues the copy spelling.
    if word == 'of':
        if re.search(r'\bcopy$', tail):
            return -7.3
        if re.search(r'\bcopies$', tail):
            return -4.1
    if tail.endswith(('cop', 'kop')) and s.startswith(('i', 'y')):
        endings = ('ia', 'ie', 'ier', 'iers', 'ied', 'i', 'iya')
        strong = s in endings or current == 'ии'
        return -7.3 if strong else -2.7

    # The cop/kop sequence can straddle two or three tokenizer pieces.
    if tail.endswith(('c', 'k')) and s.startswith('op'):
        if s == 'opy':
            return -9.3
        if s == 'ops':
            return -4.0
        if s.startswith('oper'):
            return -2.5
        if previous.strip() == 'к' and s == 'op':
            return -11.5
        if s in ('op', 'opi', 'opia', 'opies', 'opp'):
            return -8.6 if tail.endswith('k') else -6.0
        return -1.5
    if tail.endswith(('co', 'ko')) and s.lstrip('-').startswith('p'):
        return -4.6 if s.lstrip('-') in ('p', 'pi', 'py', 'po') else -0.5
    if s == 'op' and tail.endswith('p'):
        return -2.0  # pop-like spellings, including Cyrillic поп
    if s == 'p' and tail.endswith(('c', 'k')):
        return -2.5  # split cp abbreviation
    if tail.rstrip().endswith('back') and word in ('up', 'ups', 'stop'):
        return -3.0
    if ((tail.endswith(('c', 'k')) and re.match(r'[aeiuy]p', s))
            or re.search(r'[ck][aeiuy]$', tail) and s.startswith('p')):
        return -0.6 if len(s) <= 3 else 0.0

    if word == 'copy':
        if s.startswith('_'):
            return -3.9
        return -7.8 if roman(previous).strip() in ('a', 'an') else -5.4
    if word in COPY_FORMS:
        return COPY_FORMS[word]
    if word == 'cop':
        return -1.5 if current.strip().isupper() else -3.1
    if word == 'kop':
        return -4.6
    if word.startswith('ocop'):
        return -10.5
    if word.startswith('kopi') and len(word) <= 5:
        return -3.5
    if word.startswith(('cop', 'kop')) and len(word) <= 5:
        return -1.3
    if word in ('cp', 'scp'):
        return -0.8
    if word in ('cup', 'cups'):
        return -0.2
    return 0.0


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    if carry is None or carry[0] != document:
        previous, tail, position = '', '', 0
    else:
        _, previous, tail, position = carry
    current = prefix.token_strings[-1]
    value = response(previous, current, position, tail)
    tail = (tail + roman(current))[-16:]
    return (document, current, tail, position + 1), float(value)

programs.haiku:
"""LaTeX command names. This component goes negative on the name of a LaTeX command that
defines or typesets something in a special way: macro definitions (\\newcommand), the chemistry
and unit packages (\\ce, \\pu), colour and boxes (\\color, \\boxed), text and math fonts
(\\mathrm, \\text), and spacing or layout (\\rule, \\hspace, \\phantom). It is weaker on the '{'
that opens such a command's argument, and slightly negative on math arrows (⇒, →). Everyday
math commands (\\frac, \\left, \\alpha, \\begin, \\sqrt) and ordinary prose stay at 0.

The program reads the text it has seen so far. When the token is a letter run that follows a
backslash, it adds up the command name read so far (so "boldsymbol" is "bold" then "symbol")
and looks that name up. Values are typical activations in the training text."""
import re

READS = ()

# Typical activation on a command's name, by kind of command.
MACRO_DEFINITION = {"newcommand": -12.0, "renewcommand": -12.0, "new": -3.4}
CHEMISTRY = {"pu": -7.5, "ce": -4.0}
COLOUR_AND_BOX = {"color": -6.0, "boxed": -5.4, "fbox": -3.0, "mbox": -2.4}
LARGE_TEXT = {"Large": -4.7, "large": -4.5}
MATH_FONTS = {"mathrm": -2.0, "mathbf": -2.0, "bf": -1.5, "boldsymbol": -1.2, "mathbb": -0.8,
              "mathcal": -0.6, "rm": -0.8, "bb": -0.8, "cal": -0.7, "mathop": -1.9,
              "operatorname": -1.6, "bold": -0.4, "display": -0.8, "displaystyle": -0.4}
TEXT_FONTS = {"text": -1.3, "textbf": -1.3, "textnormal": -1.4, "textrm": -1.4, "textit": -1.0,
              "footnotesize": -0.7}
SPACING = {"rule": -4.4, "pars": -4.5, "hspace": -1.9, "phantom": -1.8, "nonumber": -2.0,
           "quad": -1.0, "label": -0.9, "ensuremath": -1.3, "hline": -0.7, "limits": -1.4,
           "d": -1.5}
ACCENTS = {"vec": -0.7, "hat": -0.4, "overline": -0.35, "widetilde": -0.4,
           "overrightarrow": -0.9, "overset": -1.4, "underset": -1.4, "stackrel": -1.5,
           "rightarrow": -0.25}
ARROWS_IN_COMMANDS = {"map": -4.7, "Longrightarrow": -2.4, "Rightarrow": -0.5}

VALUES = {}
for group in (MACRO_DEFINITION, CHEMISTRY, COLOUR_AND_BOX, LARGE_TEXT, MATH_FONTS,
              TEXT_FONTS, SPACING, ACCENTS, ARROWS_IN_COMMANDS):
    VALUES.update(group)

BRACE_SCALE = 0.5                                  # the '{' that opens an argument
MATH_ARROWS = {" ⇒": -0.8, " →": -0.2, "→": -0.4}  # arrows written in math


def command_so_far(strings, p):
    """The LaTeX command name read up to token p: the letters after a backslash, or None."""
    name = ""
    q = p
    while q >= 0 and re.fullmatch(r"[A-Za-z]+", strings[q]):
        name = strings[q] + name
        q -= 1
    if q < 0:
        return None
    m = re.search(r"\\([A-Za-z]*)$", strings[q])
    if m is None:
        return None
    return m.group(1) + name


def step(carry, prefix, upstream):
    s = prefix.token_strings
    p = len(s) - 1
    tok = s[p]
    value = 0.0
    if tok in MATH_ARROWS:
        value = MATH_ARROWS[tok]
    elif re.fullmatch(r"[A-Za-z]+", tok):
        name = command_so_far(s, p)
        if name is not None:
            value = VALUES.get(name, 0.0)
    elif tok.rstrip("\\") == "{" and p > 0:
        name = command_so_far(s, p - 1)
        if name in VALUES:
            value = BRACE_SCALE * VALUES[name]
    return carry, float(value)

programs.sol:
"""Backslash formatting: TeX row breaks versus escaped source strings.

Recent TeX commands identify mathematical markup. Doubled backslashes there
are strongly positive; in code strings they are negative, especially just
inside a quote. Deeply nested escaping has a weaker negative response.
A newline immediately after a TeX row break retains some positive response.
Small background biases cover document starts, indentation and opening braces.
"""
import re

READS = ()
TEX = re.compile(
    r'\\(?:begin|end|frac|sum|sqrt|left|right|quad|qquad|text|mathrm|'
    r'displaystyle|alpha|beta|sigma|theta|psi|phi|ell|partial|overline|'
    r'nabla|mu|tau|lim|rightarrow|nonumber|hfill|wedge|hat|delta)\b'
)
QUOTED_ESCAPE = re.compile(r'\\["\']')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    previous = '' if first else carry[1]
    token = prefix.token_strings[-1]
    value = -0.11 if first else 0.002
    if not first:
        if token.isspace():
            if token.count('\xa0') >= 3:
                value = 0.17
            elif '\n' not in token and len(token) >= 3:
                value = 0.02
        elif token.strip() == '{':
            value = 0.05
    if '\\' in token or (previous.endswith('\\') and token.isspace()):
        math = (len(TEX.findall(previous)) >
                len(QUOTED_ESCAPE.findall(previous)))
        if '\\\\' in token:
            if math:
                value = 1.7 if '\n' not in token else 1.1
            else:
                value = -0.65
                if token.count('\\') > 2:
                    value = -0.25
                elif (previous.endswith(('"', "'")) or
                      '"' in token or "'" in token):
                    value = -1.0
                elif '\\\\\\' in previous:
                    value = -0.3
        elif (math and '\n' in token and
              ('\\' in token or previous.endswith('\\'))):
            value = 0.75
    elif previous.endswith('\\') and TEX.search(previous):
        if token == 'cr':
            value = 2.2  # Plain TeX's row-break command.
        elif token == 'h':
            value = 0.75  # Start of the horizontal-fill command.
    return (doc, (previous + token)[-400:]), value

"""A lexical approximation to generic-person references.

It gives negative pulses to human-reference nouns and indefinite pronouns.
'No one', colloquial 'guy'/'folks', and split human-pronoun endings are
especially strong. Determiners distinguish numeral 'one' from pronominal
'one', and help distinguish a person from a generic adjective ('individual').
Modifier cues include figurative people (public figures, governing bodies).
Common translations, person counters and honorifics extend the rule.
Membership words get a small positive value; unrecognized tokens get zero.
The byte tail resets between documents. This omits much contextual variation.
"""
import re

READS = ()

NOUNS = {
    'people': -2.0, 'person': -1.5, 'persons': -1.5,
    'individuals': -1.9, 'individual': -0.4,
    'guy': -5.4, 'guys': -3.0, 'folks': -5.7, 'folk': -1.9,
    'lady': -3.8, 'ladies': -1.8, 'girl': -1.3, 'girls': -0.9,
    'man': -0.3, 'men': -0.6, 'woman': -0.5, 'women': 0.0,
    'boy': -0.6, 'boys': -0.6, 'kid': -1.5, 'kids': -0.6,
    'dude': -4.8, 'fellow': -1.3, 'fellows': -1.3,
    'gentleman': -1.3, 'gentlemen': -1.3,
    'soul': -0.9, 'souls': -2.5, 'company': -0.3,
    'firm': -0.5, 'firms': -0.5, 'organizations': -0.7,
    'organization': -0.4, 'group': -0.2, 'groups': -0.25,
    'member': 0.15, 'members': 0.8,
    'bodies': -0.9, 'voices': -1.2, 'voice': -0.45,
    'entities': -0.6,
}
PRONOUNS = {
    'someone': -2.5, 'somebody': -3.3,
    'anyone': -3.2, 'anybody': -5.0,
    'everyone': -2.9, 'everybody': -3.4, 'nobody': -6.0,
    'whoever': -1.5, 'whomever': -1.5,
    'niemand': -7.6, 'jemand': -4.3, 'iemand': -6.0,
    'nadie': -5.6, 'quién': -4.0,
    'qualcuno': -4.3, 'nessuno': -3.2,
}
TRANSLATIONS = {
    'personne': -2.5, 'personnes': -2.7, 'personas': -2.3,
    'persona': -1.3, 'persone': -1.1, 'pessoa': -2.5,
    'gente': -1.7, 'gens': -2.0, 'insan': -0.9,
    'leute': -6.0, 'volks': -4.0, 'mann': -1.3, 'frau': -1.4,
    'лю': -3.0, 'человека': -1.0,
}
DEFINITE = {'the', 'this', 'that', 'same'}
QUANTIFIERS = {'many', 'most', 'other', 'few', 'more', 'some',
               'these', 'those', 'such', 'different'}
WORD = re.compile(r'([^\W\d_]+)$')


def predict(text, token):
    text = text.replace(r'\n', '\n').replace(r'\t', '\t')
    if re.search(r"quelqu['’]un$", text.lower()):
        return -6.5
    if re.search(r"y['’]all$", text.lower()):
        return -5.0
    # Person-counting characters also occur without spaces in Asian scripts.
    if token == '人':
        qualifier = (r'[\d一二三四五六七八九十百'
                     r'几幾多少这這那哪些有无無他每友熟]')
        return -2.0 if re.search(qualifier + '人$', text) else -0.15
    if token in {'各位', '人士', '有人', '個人', '个人',
                 '誰', '谁', 'คน'}:
        return -1.6
    if token == '達' and text.endswith('友達'):
        return -2.4
    if token in {'位', '名'}:
        counter = (r'[\d一二三四五六七八九十百'
                   r'两兩這这那幾几諸诸有]' + token + '$')
        return -2.6 if re.search(counter, text) else 0.0
    if token in {'様', 'さま'}:
        group = ('皆様', '皆さま', '客様', '客さま')
        return -4.4 if text.endswith(group) else -1.2
    match = WORD.search(text)
    if not match or not token or not token[-1].isalpha():
        return 0.0
    spelling = match.group()
    word = spelling.lower()
    before = text[:match.start()].rstrip(' -')
    prev_match = WORD.search(before)
    prev = prev_match.group().lower() if prev_match else ''
    split = token.strip().lower() != word
    if word in PRONOUNS:
        value = PRONOUNS[word]
        if word.endswith(('body', 'one')) and split:
            value = -8.0 if word.endswith('body') else -6.5
        elif spelling[0].isupper() and word in {'someone', 'somebody', 'anyone'}:
            value -= 0.6
        return value
    if word == 'one':
        if prev == 'no':
            return -8.7
        if prev in {'any', 'some'}:
            return -2.6
        if prev in DEFINITE | {'each', 'every', 'which', 'another',
                                'first', 'second', 'last', 'new', 'previous'}:
            return -0.9
        if before.lower().endswith('the only'):
            return -1.2
        return 0.0
    if word == 'ones':
        return -0.6
    if word == 'else':
        if prev in PRONOUNS or prev == 'one':
            return -4.5
        return -1.5 if prev in {'somewhere', 'anywhere', 'what', 'whatever'} else 0.0
    if word in {'us', 'you'} and prev == 'of' and not spelling.isupper():
        return -3.8 if word == 'us' else -2.8
    if re.fullmatch(r'люд(и|ям|ях|ей|ьми)?', word):
        return -4.3 if split and spelling[0].isupper() else -2.7
    if word == 'body':
        if prev in {'any', 'every', 'public', 'full'}:
            return -3.6
        if prev in {'a', 'an', 'this', 'administrative', 'notified',
                    'governing', 'management', 'dead'}:
            return -1.8
    if word in {'figure', 'figures'} and prev in {
        'public', 'historical', 'key', 'prominent', 'religious',
        'important', 'authority', 'heroic', 'significant'}:
        return -4.2 if word == 'figures' else -2.2
    if word == 'party' and prev in {'third', '3rd'}:
        return -1.8
    if word == 'monde' and before.lower().endswith('tout le'):
        return -3.6
    if word in TRANSLATIONS:
        return TRANSLATIONS[word]
    if word.endswith('guy') and word != 'nguy':
        return -7.2 if split else (-3.7 if spelling[0].isupper() else -5.4)
    if word not in NOUNS:
        return 0.0
    value = NOUNS[word]
    if word == 'people':
        if prev in QUANTIFIERS:
            value = -3.2
        elif prev in {'the', 'living', 'its', 'our'}:
            value = -1.1
    elif word == 'person':
        if prev in DEFINITE:
            value = -2.1
        elif prev in {'any', 'another', 'other', 'one', 'every'}:
            value = -2.4
    elif word == 'individual':
        if prev in {'an', 'another', 'any', 'this'}:
            value = -1.8
        elif prev in DEFINITE:
            value = -1.2
    elif word == 'man':
        if prev in DEFINITE | {'old', 'young', 'dead', 'elderly'}:
            value = -2.2
        elif prev == 'a':
            value = -1.2
    elif word == 'lady' and prev == 'young':
        value = -5.7
    if word in {'folks', 'lady'} and split:
        value *= 1.8
    elif spelling[0].isupper() and word in {'people', 'person', 'lady', 'man'}:
        value *= 0.55
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail = carry[1] if carry and carry[0] == doc else b''
    token = prefix.token_bytes[-1]
    tail = (tail + token)[-160:]
    return (doc, tail), predict(tail.decode('utf-8', 'replace'),
                                token.decode('utf-8', 'replace'))

programs.haiku:
"""Generic-person reference.

The component is negative on the word that refers to an unspecified person or people,
whether a noun or a pronoun: "people", "person", "someone", "no one", "everyone else",
"all of us", "those of you", "somebody's". It is strongest on indefinite pronouns and
on "one" after "no", and weaker on plain person nouns. Quantifiers and determiners before
a person noun ("many people", "the man") make it stronger. Everything else is zero.
"""

READS = ()

# Indefinite pronouns for an unspecified person (strong).
INDEFINITE = {"someone", "anyone", "everyone", "everybody", "anybody", "somebody",
              "nobody", "niemand", "jemand", "alguien", "nadie", "personne", "quelqu'un"}

# Nouns for people, with a typical strength (negative = refers to people).
PERSON_NOUN = {
    "people": -2.0, "person": -1.6, "persons": -1.5, "personnes": -2.5, "personas": -2.0,
    "gente": -2.0, "individuals": -1.8, "individual": -1.0, "man": -0.8, "men": -0.7,
    "woman": -0.8, "guy": -5.0, "guys": -3.0, "dude": -5.0, "lady": -4.0,
    "ladies": -2.0, "girl": -1.2, "fellow": -1.9, "folks": -6.0, "folk": -4.0,
    "hombre": -2.6, "voices": -1.3,
    "人": -0.6, "人们": -1.5, "様": -1.5, "人员": 0.7, "members": 1.0,
    "member": 0.2,
}
POSSESSIVES = {"his", "her", "their", "our", "my", "your", "its"}
QUANTIFIERS = {"no", "any", "some", "every", "each", "many", "most", "few", "all", "other",
               "those", "these", "young", "two", "three", "several", "of", "the", "this"}


def step(carry, prefix, upstream):
    toks = [s.strip().lower() for s in prefix.token_strings[-3:]]
    word = toks[-1]
    before = toks[-2] if len(toks) > 1 else ""
    if word in INDEFINITE:
        value = -6.0 if word == "nobody" else -3.0
    elif word in PERSON_NOUN:
        value = PERSON_NOUN[word]
        if value < 0 and before in QUANTIFIERS:
            value *= 1.5
        if value < 0 and before in POSSESSIVES:
            value *= 0.3
    elif word == "body" and before in {"some", "any", "no", "every", "full"}:
        value = -7.0
    elif word == "one" and before == "no":
        value = -7.5
    elif word == "one" and before in {"any", "every", "each", "some", "which", "only"}:
        value = -2.0
    elif word == "one":
        value = -0.3
    elif word == "else" and (before in INDEFINITE or before == "one"):
        value = -5.0
    elif word in {"us", "you"} and before == "of":
        value = -3.0
    elif word == "monde" and before == "le":
        value = -3.5
    else:
        value = 0.0
    return carry, float(value)

programs.sol:
"""A sparse lexical/formatting approximation, not a general semantic model.

Positive writes mark an opening Title colon, newlines after short educational
labels, dotted math-library members, selected C headers, government-domain
suffixes, and heat/mass/energy transfer compounds. Negative writes mark
transparency, academic press/writing, and Chinese field-of-study adverbials
ending in 学上 (or traditional 學上). Other tokens stay near zero, apart from
small document-initial offsets by character class. State resets per document;
only the last 100 characters of the current line are retained.

Fixed strengths approximate the observed response; many smaller lexical and
context-sensitive variations are deliberately omitted.
"""
import re

READS = ()

# The names describe familiar educational resource labels, not token IDs.
HEADING_VALUES = {
    'Math': 2.7,
    'Worksheet': 1.7,
    'Lesson Plan': 1.4,
    'Science': 1.2,
    'Chemistry': 0.4,
    'Question': 2.7,
    'Article': 2.0,
    'Stats': 0.8,
    'Title': 1.2,
}


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != document:
        position, previous, line = 0, '', ''
    else:
        _, position, previous, line = carry
        position += 1
    value = 0.003
    if position == 0:
        if token.isascii() and token.isdigit():
            value = 0.30
        elif token.isspace():
            value = 0.14
        elif token.strip().isascii() and token.strip().isalpha():
            value = 0.15
    if position == 1 and previous == 'Title' and token == ':':
        value = 8.28
    elif token.startswith('.') and re.search(r'\bmath$', previous, re.I):
        # Different elementary operations have different response strengths.
        if token == '.':
            value = 0.63
        elif token in ('.pow', '.exp'):
            value = 0.55
        elif token == '.abs':
            value = 1.2
        elif token == '.log':
            value = 3.7
        else:
            value = 2.3
    elif token == '\n':
        value = HEADING_VALUES.get(line.strip(), value)
    elif token == '\n\n' and line.strip() in ('Math', 'Chemistry'):
        value = 0.35
    elif token == '.gov':
        value = 1.4
    elif token == '.h':
        header = previous.strip()
        if header == 'time':
            value = 1.38
        elif header == 'string':
            value = 1.21
        elif header in ('stdio', 'stdlib'):
            value = 0.35
    elif previous.strip().lower() in ('heat', 'mass', 'energy') and (
        token.strip().lower() in ('transfer', 'exchange')
    ):
        value = 1.4
    elif previous.strip().lower() == 'academic' and (
        token.strip().lower() in ('press', 'writing')
    ):
        value = -1.9
    elif token in ('上', '上的') and previous.endswith(('学', '學')):
        # Chinese field-of-study adverbials: e.g. 数学上, "mathematically".
        value = -2.0
    elif token.strip().lower() in ('transparent', 'transparency'):
        value = -0.43
    elif token == '透明':
        value = -1.73
    line = (line + token).rsplit('\n', 1)[-1][-100:]
    return (document, position, token, line), value

programs.haiku:
"""layers.1.mlp.down_proj:3040 -- a sparse, mostly-quiet component.

Its activation is ~0 on almost every token. It fires in a few recognisable places:

* a newline right after a bare "Math" line, and newlines inside math-worksheet
  title lists ("Math / Worksheet / Lesson Plan" pages): the strongest, 1-4 nats;
* a "." that follows "Math" in code (Math.random, Math.floor, ...);
* a colon after "Title" at the start of a document (the largest values, ~8);
* a run of middle dots ("······"), a constant ~0.42;
* the first token of a document, a small positive offset;
* a weak negative for some Chinese political/ideological nouns.

Everything else is predicted as 0. This is a hand-written approximation: it captures
the top of the distribution, not the diffuse small values on ordinary words.
"""

READS = ()

# Words that mark a math-worksheet / lesson-plan page.
MATH_WORDS = ("Math", "Worksheet")
# Chinese political and ideological vocabulary, mildly negative.
CN_POLITICAL = ("社会主义", "党的", "人民", "思想", "科学", "社会", "独立")


def step(carry, prefix, upstream):
    toks = prefix.token_strings
    cur = toks[-1]
    prev = toks[-2].strip() if len(toks) > 1 else ""
    prev2 = toks[-3] if len(toks) > 2 else ""
    if prefix.position == 0:
        return carry, 0.12  # first token of a row
    if cur == ":" and prev == "Title" and prev2 == "<|endoftext|>":
        return carry, 8.0  # "Title:" opening a new document
    if cur.strip("·") == "" and cur:
        return carry, 0.42  # run of middle dots
    if cur == "\n" and prev == "Math":
        return carry, 2.7  # newline right after a bare "Math" line
    if cur == "\n" and any(w in "".join(toks[-5:-1]) for w in MATH_WORDS):
        return carry, 1.1  # newline in a math-worksheet title list
    if cur.startswith(".") and prev in ("Math", "math"):
        return carry, 1.0  # Math.random, math.h, ...
    if cur in CN_POLITICAL:
        return carry, -0.4
    return carry, 0.0

programs.sol:
"""Recognize real-time and realization language, plus nearby spelling contrasts.

Large positives mark 'real time' in English, Chinese and Japanese. Smaller
positives mark realization/implementation words and phrasal-verb 'out'.
Negative rules distinguish ree-/rei-/re- continuations and unrelated 'time'.
The constants are training means for these spelling/context classes, rounded.
This is a lexical approximation, not an account of every small activation.
Only the last 100 characters are carried, resetting at document boundaries.
"""
import re
import unicodedata

READS = ()


def activation(s, before):
    t = s.casefold()
    word = t.strip()
    prev = before.casefold()
    # English, Chinese and Japanese ways to say 'real time'.
    if re.search(r'real-?$', prev) and word in (
        'time', '-time', 'times', '-times'):
        return 12.12 if '-' in word else 8.75
    if word in ('realtime', 'real-time'):
        return 10.75
    if word.startswith('实时'):
        return 7.64
    if prev.endswith(('实', '實', '実')) and word in ('时', '時', '時間'):
        return 4.88 if word == '時間' else 13.26
    if word == 'タイム' and prev.endswith('リアル'):
        return 11.25
    if word.startswith(('实现', '實現')):
        return 2.08
    if prev.endswith(('实', '實', '実')) and word.startswith(('現', '现')):
        return 2.08
    # Whole words and subwords derived from Latin realis.
    plain = ''.join(c for c in unicodedata.normalize('NFD', word)
                    if unicodedata.category(c) != 'Mn')
    if plain.startswith(('realiz', 'realis')):
        if plain.startswith(('realist', 'realistic')):
            return 0.91
        return 2.57
    if word.startswith('réal'):
        return 2.57
    if word == 'времени' and re.search(r'реаль?н[а-я]*$', prev):
        return 6.47
    if plain in ('real', 'reality', 'realities', 'reale', 'reales'):
        return 0.19
    if not s[:1].isspace():
        m = re.search(r'[\w-]+$', prev)
        stem = m.group() if m else ''
        simple_stem = ''.join(c for c in unicodedata.normalize('NFD', stem)
                              if unicodedata.category(c) != 'Mn')
        if stem.endswith(('real', 'réal', 'unreal')):
            if word.startswith(('iz', 'is', 'it', 'al')):
                return 3.38
        if stem in ('ре', 'реал', 'реаль'):
            if word.startswith(('ал', 'аль', 'из', 'і')):
                return 3.36
        if stem == 'ré' and word == 'el':
            return 0.19
        re_stem = stem in ('re', 'prere', 'unre')
        continuation = word and (word[0].isalpha() or word[0] in '-:')
        if re_stem and continuation:
            if plain.startswith(('ed', 'el')):
                return -5.72
            if plain.startswith('e'):
                return -1.35
            if plain.startswith(('in', 'im', 'ign', 'ik', 'iv')):
                return -2.19
            if plain.startswith(('al', 'ag')):
                return 0.77
            if plain.startswith(('am', 'ar')):
                return -2.57
            if word.startswith('-'):
                return -3.77 if word.startswith('-read') else -0.76
            if word == ':':
                return 1.59
            return -0.13
        if stem == 'ре' and word.startswith('форм'):
            return -4.0
        if (simple_stem.endswith(('res', 'rez', 'resu'))
                and plain.startswith(('ol', 'ul', 'uel', 'elt', 'alt', 'u'))):
            return 1.03
    boundary = s[:1].isspace() or not before or not before[-1].isalpha()
    if boundary and re.fullmatch(r'ree[dl](?:s|ed|ing)?', plain):
        return -3.41
    if boundary and re.fullmatch(r'rei(?:gn|n)(?:s|ed|ing)?', plain):
        return -1.24
    if plain.startswith('reform'):
        return -0.4
    if plain.startswith(('resolution', 'resolu')):
        return 0.53
    if word in ('time', '-time'):
        return -0.20 if s[:1].isspace() or word[0] == '-' else -0.08
    # Completion/result senses of out, rather than spatial 'out'.
    if word == 'out':
        words = re.findall(r'[a-z]+', prev[-65:])
        if words and words[-1] in ('it', 'this', 'that', 'them', 'everything'):
            words = words[:-1]
        v = words[-1] if words else ''
        if v in ('carry', 'carried', 'carries', 'carrying'):
            return 2.87
        if v in ('rule', 'ruled', 'ruling', 'sort', 'sorted', 'sorting',
                 'play', 'plays', 'played', 'playing'):
            return 2.92
        if v in ('figure', 'figured', 'figuring', 'work', 'works',
                 'worked', 'working', 'try', 'tried', 'trying',
                 'run', 'runs', 'ran', 'running'):
            return 1.28
        return 0.11
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    before = carry[1] if carry is not None and carry[0] == doc else ''
    s = prefix.token_strings[-1]
    value = activation(s, before)
    return (doc, (before + s)[-100:]), value

"""A short-range lexical/grammatical approximation.

The strongest negative responses are hedges (kind of, sorta) and quantitative
'about'; topic-information uses of 'about' are much less negative or positive.
Indefinite kinds/ways, partitives and 'as much' have positive responses. Only
the last two tokens and a short text tail are kept. There are also negative
responses for Asian approximation markers and a few discourse particles;
unmatched tokens predict zero. This is a partial, not exhaustive account.
"""
import re
import wordnet

READS = ()
COPULAS = set('am is are was were be been being'.split())
COPULAS |= {"'s", '’s', "'m", '’m', "'re", '’re'}
AUXILIARIES = set('have has had will would should shall must may might'.split())
CONTRACTIONS = {"'ve", '’ve', "'d", '’d', "'ll", '’ll'}
PREPOSITIONS = set(
    'of to for at from between by after before over under within until '
    'since in with above below'.split())
MEASURING = set(
    'take cost worth add carry cover contain include weigh last spend walk '
    'ride average hold earn'.split())
TYPE_SELECTORS = set(
    'a an this that these those the my your his her our their its '
    'each every all no whatever which'.split())
ADVERBS = set('never ever already definitely probably certainly often'.split())
# These compounds use the character for a contract, reservation, saving, etc.,
# not for an approximate quantity.
NON_QUANTITY = set(
    '契約 予約 預約 预约 違約 违约 制約 制约 節約 节约 紐約 里约 盟约'.split())


def response(s, p, pp, tail):
    w = s.strip().lower()
    if w in {'kinda', 'sorta'} or (
        not s.startswith(' ') and re.search(r'\b(?:kind|sort)a$', tail.lower())
    ):
        return -7.2
    if w == 'about':
        if p in PREPOSITIONS:
            return -4.9
        roots = {p} | set(wordnet.base_forms(p))
        if roots & MEASURING:
            return -5.6
        if roots & {'go', 'set', 'locate', 'situate'}:
            return -3.3
        if p in COPULAS or p in {'has', 'have', 'had'}:
            return -2.9
        if p in {'just', 'around', 'round'}:
            return -4.9
        if p in {'and', 'that', 'least', 'than', 'on', 'get'}:
            return -3.3
        if p in {'information', 'info', 'more', 'news', 'out', 'enough'}:
            return 0.95
        if p in {'care', 'forget', 'informed'}:
            return 1.65
        if p in {'ask', 'asks', 'asked', 'asking'}:
            return 0.75
        if p == 'how' or s.strip()[0].isupper():
            return -1.4
        if not p or not any(c.isalpha() for c in p):
            return -1.95
        return -0.3
    if w in {'kind', 'sort'}:
        scale = 1.0 if w == 'kind' else 0.45
        if p in {'some', 'any'}:
            return 2.8 * scale
        if p == 'a':
            return 2.3 if w == 'kind' else 0.45
        if p in {'what', 'which', 'whatever'}:
            return 1.5 * scale
        if p in {'first', 'second', 'third', 'its', 'every', 'all'}:
            return 2.9 * scale
        if p in COPULAS or p in AUXILIARIES or p in {'just', 'it', 'i'}:
            return -1.0 * scale
        return 0.2 if w == 'kind' else 0.0
    if w == 'of' and p in {'kind', 'sort'}:
        if pp == 'some':
            return 2.7
        if pp == 'any':
            return 0.9
        if pp == 'what':
            return 0.1
        if pp in COPULAS or pp in {'i', 'it', 'you', 'just', ',', '.', '('}:
            return -9.0
        if pp in TYPE_SELECTORS or 'adjective' in wordnet.parts_of_speech(pp):
            return -1.4
        return -5.2
    if w == 'of' and p in {
