"""Hedges and approximations, read as negative activations.

Component layers.1.mlp.down_proj:3042 is silent almost everywhere. Its large values come from
a few word families, and the sign says which way they point:

- Negative, strongest: "about" used as an approximate amount ("took about 20 minutes",
  "for about 2 km", "is about 23"). Also the hedge "kind of" / "sort of" ("it is kind of fun",
  "I'm sort of"), "kinda"/"sorta", and "way" as an intensifier ("way too big").
- Negative, milder: "approximately", "roughly", and approximating words in Chinese, Japanese,
  Korean and Russian (約, 约, 略, 大约, 약, около).
- Positive: "kind" / "sort" as a noun after "some" or "any" ("some sort of", "any kind"),
  "a kind" ("one of a kind"), "as much as", "otherwise", "ever", and "half of" / "a lot of".

Plain "about" with a topic ("talk about", "questions about") stays at zero, and "care about",
"information about" lean slightly positive. The program reads only the previous one or two
tokens, inside the same document.
"""

READS = ()

# "about" after these words means an approximate amount: strongly negative
QUANTITY_BEFORE = {"for", "took", "take", "taking", "to", "of", "between", "from", "at", "by", "within",
                   "above", "below", "covering", "up", "around", "worth", "just", "carrying", "averaging",
                   "holding", "put", "includes", "include", "located", "riding", "using", "hold", "last"}
# "about" after a copula or conjunction ("is about", "and about"): moderately negative
COPULA_BEFORE = {"is", "was", "are", "were", "be", "and", "or", "than", "that", ",", "in", "on"}
# "about" after a topic verb or noun ("talk about", "questions about"): no effect
TOPIC_BEFORE = {"think", "thinking", "thought", "talk", "talks", "talking", "talked", "know", "learn",
                "learned", "read", "write", "writing", "question", "questions", "story", "stories",
                "worry", "worried", "concerned", "book", "books", "article", "heard", "curious", "debate",
                "discussion", "information", "info", "news", "say", "ask", "asked", "tell", "told"}
# "about" after these is a topic ("care about", "informed about"): mildly positive
CARE_BEFORE = {"care", "cares", "caring", "informed", "more", "all", "asking",
               "forget", "out", "everyone", "everything", "something"}
# words before "kind"/"sort" that make "kind of" a hedge ("it is kind of fun", "I'm sort of")
HEDGE_BEFORE_KIND = {"is", "was", "it's", "s", "'s", "m", "im", "just", "and", "so", "to", "be", "were",
                     "are", "really", "sounds", "feel", "seems", "become", "became", "have", "has", "like",
                     "you", "i", "it", "we", "they", "he", "she", "that's", "'re", "bit", "or", "but"}
PARTITIVE = {"half", "lot", "thousands", "dozens", "hundreds", "millions", "couple"}
# words before "way" that make it an intensifier ("way too big", "is way better")
INTENSIFIER_BEFORE = {"i'm", "im", "it's", "is", "was", "were", "are", "be", "too", "so", "really", "'s",
                      "'re", "getting", "growing", "make", "’s", "’m"}
