    tok = _tok(prefix, 0)
    prev = _tok(prefix, 1)
    prev2 = _tok(prefix, 2)
    value = 0.0
    if tok == "about":
        if prev in QUANTITY_BEFORE:
            value = -5.0
        elif prev in COPULA_BEFORE:
            value = -3.5
        elif prev in TOPIC_BEFORE:
            value = 0.0
        elif prev in CARE_BEFORE:
            value = 1.0
        else:
            value = -1.0
    elif tok == "of" and prev in ("kind", "sort"):
        if prev2 in ("some", "any"):
            value = 2.5
        elif prev2 in HEDGE_BEFORE_KIND:
            value = -8.0
        else:
            value = -1.5
    elif tok == "of" and prev in PARTITIVE:
        value = 0.7
    elif tok == "a" and prev in ("kind", "sort"):
        value = -6.0
    elif tok in ("kinda", "sorta"):
        value = -6.0
    elif tok == "way":
        if prev in INTENSIFIER_BEFORE:
            value = -4.5
        elif prev == "a" and prev2 == "such":
