    elif tok == "much" and prev == "as":
        value = 3.0
    elif tok in ("approximately", "roughly"):
        value = -0.7
    elif tok in APPROX_CJK:
        value = -2.5
    elif tok in ("kind", "-kind") and prev in ("any", "some", "a", "of", "one"):
        value = 3.0
    elif tok in ("otherwise", "ever"):
        value = 0.6
    return carry, value

