"""Approximate negative responses to fragmented words and broken encodings.

Late cased pieces of a word have negative responses, stronger when earlier
pieces use multibyte characters. NUL-separated letters have a particularly
clear within-word ramp. Hexadecimal byte escapes and an initial 'Title:' heading are
separate large responses. Small lexical fluctuations are left unmodeled.
"""
import re

READS = ()
ESCAPED_BYTES = re.compile(r'(?:\\x[0-9a-fA-F]{2}){3}[A-Za-z]*$')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, 0, (), 0, 0, 0)
    _, pieces, recent, position, letters, digits = carry
    s = prefix.token_strings[-1]
    b = prefix.token_bytes[-1]
    before = pieces
    if not s[:1].isalnum():
        pieces = 0
    pieces += 1

    value = -0.01
    if pieces >= 4:
        level = min(pieces - 4, 2)
        if any(c.islower() for c in s):
            multibyte = (len(recent) >= 3 and recent[-3]
                         and recent[-3][0] >= 192)
            if multibyte:
                curve = (-0.16, -0.37, -0.68)
            else:
                curve = (-0.08, -0.18, -0.18)
            value = curve[level]
        elif any(c.isupper() for c in s):
            value = (-0.10, -0.21, -0.19)[level]
    if s[:1].isspace() and any(c.islower() for c in s):
        if digits >= 2:
            value -= 0.06
        elif before >= 3:
            value -= 0.04

    # Letters separated by NULs, as in UTF-16 misread as single-byte text.
    if b != b'\x00':
        letters = letters + len(s) if s.isalpha() else 0
    if recent and recent[-1] == b'\x00':
        if s.isalpha():
            value = -0.3 - 0.65 * min(4, letters - 1)
        elif s.isspace():
            value = -0.3
    if b == b'\x00' and recent:
        value = max(0.05, 0.3 - 0.04 * (letters - 1)) if letters else -0.12

    tail = b''.join(recent).decode('utf-8', 'replace')
    if s.isascii() and s.isalpha() and ESCAPED_BYTES.search(tail + s):
        value = -3.0
    if s == ':' and recent and recent[-1] == b'Title' and position == 1:
        value = -9.97

    digits = digits + 1 if s.isdigit() else 0
    if not s[-1:].isalnum():
        pieces = 0
    state = (doc, pieces, (recent + (b,))[-16:], position + 1, letters, digits)
    return state, value

