    (('highlight',), -0.16),
    (('highland',), -1.27),
    (('highway',), -0.65),
    (('height',), -0.34),
    (('hoch', 'hohe'), -6.32),       # German high
    (('höh', 'höch'), -2.90),       # German height/higher/highest
    (('haut',), -2.74),             # French high
    (('выс',), -2.25),              # Russian high/height prefix
    (('hyper',), -1.26),            # excessive or above
