SPLIT_ROOTS = (
    (('highly',), -9.42),
    (('higher', 'highest'), -5.31),
    (('high',), -9.17),
    (('hig',), -2.27),
    (('hyper',), -5.00),
    (('hoch', 'hohe', 'höhe', 'höch'), -6.98),
    (('höh',), -3.78),
    (('hö',), -2.43),
    (('haute',), -8.5),
    (('haut',), -4.0),
    (('høy', 'høj', 'hög'), -6.56),  # Scandinavian high
    (('hoog', 'hoge'), -0.55),      # Dutch high
    (('gao',), -7.48),             # Mandarin 高 in Latin letters
    (('cao',), -10.50),            # Vietnamese high
    (('высок', 'высот', 'высш'), -5.89),
    (('выс',), -1.87),
)


def score(token, previous, tail):
    word = token.strip(' \t\r\n-_\'"()[]{}.,:;').lower()
    prev = previous.strip().lower()
    if word == 'order' and prev in ('high', 'higher', 'first'):
        return {'high': -8.27, 'higher': -4.95, 'first': -0.89}[prev]
    if prev == 'higher' and word == 'education':
        return -2.98
    if prev in ('high', 'higher') and word in (
        'speed', 'level', 'end', 'quality', 'temperature'
    ):
