    if prev == '高' and regex.match(r'\p{Script=Han}', token):
        return -0.70

    if token[:1].isalpha() and tail:
        joined = tail.lower() + token.lower()
        boundary = len(tail)
        for roots, value in SPLIT_ROOTS:
            for root in roots:
                start = joined.rfind(root)
                if not (0 <= start < boundary < start + len(root)):
                    continue
                if root == 'cao' and (tail.lower() != 'ca' or token.lower() != 'o'):
                    continue
                if root in ('haut', 'haute') and start != 0:
                    continue
