            return -1.21
        if tail.lower().startswith(('höh', 'höch', 'hoh', 'hoch')):
            return -0.36
        if tail.lower() in ('high', 'higher', 'height'):
            return -0.62
        if prev == '고' and regex.match(r'\p{Script=Hangul}', token):
            return -0.59

    if '高' in word:
        return -2.26 if word == '高' else -1.18
    if '大' in word:
        return -0.69 if word == '大' else -0.30
    if word in ENGLISH_HIGH:
        if word == 'higher' and token.strip()[:1].isupper():
            return -2.78
        if word == 'high' and token[:1].isalpha() and tail:
            return -2.47
        return ENGLISH_HIGH[word]
    if word.startswith('hoch') and token.strip()[:1].isupper():
        return -10.71
    if word == 'hö':
        return -2.90
    if word == '고':
        return -0.57
    for roots, value in WHOLE_ROOTS:
        if word.startswith(roots):
            return value
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous, tail = ('', '') if carry is None or carry[0] != doc else carry[1:]
    token = prefix.token_strings[-1]
    value = score(token, previous, tail)
    letters = re.search(r'[^\W\d_]+$', token)
    if letters:
        tail = ((tail if letters.start() == 0 else '') + letters.group())[-12:]
    else:
        tail = ''
    return (doc, token, tail), value

