"""High-word detector: a negative spike on the token that completes a word meaning
'high' (or 'height', 'higher', 'highly', in German, Norwegian, Russian, Vietnamese,
Chinese), with a strength per word family. Everything else predicts 0."""
import re

READS = ()

# Whole words, matched exactly (lower case).
WORDS = {"highly": -7.0, "cao": -10.0, "gao": -4.0}
# Word stems, matched anywhere inside the current word; the longest stem wins.
STEMS = {
    "hoch": -8.0, "hohe": -8.0, "höch": -6.0, "höh": -3.0, "høy": -7.0, "hoog": -1.7,
    "haute": -4.0, "высок": -6.8, "высот": -5.7, "высш": -5.0, "выс": -3.0,
    "high": -1.5,
}
# Words that contain a stem but do not mean 'high', and are excluded.
EXCLUDE = ("highlight", "highway", "thigh", "höchst", "hohepunkt", "выстрел", "выслеж")
CHINESE_GAO = -2.0  # 高, 'high/tall' in Chinese and Japanese, inside a token
WORD = re.compile(r"[^\W\d_]+$")
STEM_ORDER = sorted(STEMS, key=len, reverse=True)


def word_at(text):
    """The letters ending the text: the word the current token is part of."""
    m = WORD.search(text)
    return m.group(0).lower() if m else ""


def value_of(word):
    if word in WORDS:
        return WORDS[word]
    if any(x in word for x in EXCLUDE):
        return 0.0
    for stem in STEM_ORDER:
        if stem in word:
            return STEMS[stem]
    return 0.0


def step(carry, prefix, upstream):
    t = prefix.position
    word = word_at(prefix.text_prefixes[t])
    prev = word_at(prefix.text_prefixes[t - 1]) if t > 0 else ""
    value = value_of(word)
    if word == "order" and prev in ("high", "higher"):
        value = -6.0  # 'high order'
    if word == "high" and prev == "junior":
        value = 0.0  # 'junior high' school does not fire
    if value == 0.0 and "高" in prefix.token_strings[t]:
        value = CHINESE_GAO
    return carry, float(value)

