"""Document-opening syntax, with a small background response to text markers.

The main positive pulses mark code headers and English article-shaped tokens.
Unspaced words get a smaller pulse; space-prefixed words are negative.
Repeated leading middle dots, carets, or carriage returns keep their opening value.
The initial decimal prefix 12 is a separate strong negative case.
High-importance training windows motivated these boundary-local rules.
Most ordinary text is deliberately predicted as zero: small lexical and
contextual differences are not reconstructed.
"""

READS = ()
ARTICLES = {"A": 0.826, "An": 1.92, "The": 0.720}
CPP_HEADERS = {"#ifndef": 1.99, "#include": 0.94, "#pragma": 1.24,
               "#define": 0.20}


def opening_value(token):
    if token in ARTICLES:
        return ARTICLES[token]
    if token in CPP_HEADERS:
        return CPP_HEADERS[token]
    if token.startswith("/*"):
        if token == "/*":
            return 1.48
        return 1.93 if token in ("/*\n", "/**\n") else 1.30
    if token == "//":
        return 0.85
    if token == "//\n":
        return -1.52
    if token in ("import", "from", "using", "def"):
        return 1.04
    if token == "package":
        return 1.186
    if token == "class":
        return 0.58
    if token == "export":
        return 1.44
    if token in ("USE", "FROM"):
        return 2.0
    if token == "'use":
        return 1.66
    if token in ("#", "##", "###"):
        return 1.05 if token == "##" else 0.5
    if token.startswith("#!/"):
        return 0.33
    if token == "<|im_start|>":
        return 0.124
    if token and set(token) == {"·"} and len(token) >= 2:
        return -1.36
    if token and set(token) == {"^"} and len(token) >= 4:
        return -2.06
    if token == "\r":
        return -1.53
    if token.isascii() and token.isalpha():
        if len(token) == 1 and token.isupper():
            return 0.57
        if token.istitle():
            return 0.11
        if token.isupper():
            return 0.40
        if token.islower():
            return 0.10
    if token.isascii() and token.isdigit():
        return -0.10
    if token.isalpha():
        return 0.10
    if token.startswith(" ") and token.strip().isalpha():
        return -0.094
    if token.isspace():
        if "\n" in token:
            return -0.30
        if "\t" in token:
            return 0.15
        return 0.30 if len(token) >= 3 else -0.08
    return 0.0


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != document:
        position, opening, separator_run = 0, token, True
    else:
        _, position, opening, separator_run = carry
        separator_run = separator_run and token == opening
    value = 0.0
    if position == 0:
        value = opening_value(token)
    elif separator_run and token and set(token) <= {"·", "^", "\r"}:
        value = opening_value(token)
    elif position == 1:
        if opening == "<?" and token == "php":
            value = 1.389
        elif opening == "<" and token == "filename":
            value = 1.74
        elif opening == "1" and token == "2":
            value = -2.284
        elif opening == "#pragma" and token == " once":
            value = 0.456
        elif opening.startswith("/*") and token == " *":
            value = 0.27
    elif position == 2 and opening == "1":
        if prefix.token_strings[-2] == "2" and token == "2":
            value = -1.007
    if position > 0 and value == 0.0:
        if token == "://":
            value = 0.165
        elif token == "<|im_end|>":
            value = -0.041
        elif token in (r"\n", r"\t"):
            value = 0.03
    return (document, position + 1, opening, separator_run), value

