"""Layer 1 MLP down-projection, component 3046: a document-opening detector.

Inside a document this component is almost silent: its activation there is a small
wobble, about 0.05 in size, set by individual tokens in a way no simple rule describes.
Its clear behaviour is at the first token of each document (a change of document id,
or the first token of a row, where the model restarts attention and positions). There
it takes a value set by what that token looks like:

  * a source-file or markup opener (`#include`, `/*`, `//`, `<!`, `package`, `import`,
    `using`, `namespace`, ...): about +0.9;
  * a common sentence opener (`The`, `I`, `In`, `How`, ...): about +0.6;
  * any other capitalised word: about +0.15;
  * a lowercase word, or other text: about +0.1;
  * a fragment that starts mid-text (a leading space, a digit): about -0.1;
  * a newline: about -0.3.

Values are the mean activations of each class over training documents. The program
predicts 0 at every other position.
"""

READS = ()

CODE_PREFIXES = ("#", "/*", "//", "<!", "%")
CODE_WORDS = {"package", "import", "using", "namespace", "export", "module",
              "from", "def", "use", "'use", "include"}
OPENERS = {"The", "A", "An", "I", "In", "It", "He", "She", "We", "You", "They",
           "How", "What", "When", "Why", "Who", "Where", "If", "As", "At", "On",
           "For", "And", "But", "So", "By", "My", "Your", "Our", "Most", "Some",
           "Many", "Yes", "Title", "Do", "Can", "Is", "Are", "After", "Before", "With"}


def document_start(prefix):
    """True at a row's first token or where the document id changes."""
    if prefix.position == 0:
        return True
    return prefix.document_ids[-1] != prefix.document_ids[-2]


def opener_value(token):
    """The component's activation at a document's first token."""
    if token.startswith(CODE_PREFIXES) or token.strip().lower() in CODE_WORDS:
        return 0.9
    if token[:1] in ("\n", "\r"):
        return -0.3
    if token[:1] in (" ", "\t") or token[:1].isdigit():
        return -0.1
    if token in OPENERS:
        return 0.6
    if token[:1].isupper():
        return 0.15
    return 0.1


def step(carry, prefix, upstream):
    if not document_start(prefix):
        return carry, 0.0
    return carry, opener_value(prefix.token_strings[-1])

