- the '//' of an http(s) URL (about 2.1);
- a '{' right after LaTeX \\begin or \\end (about 1.15);
- a JSON '{"' starting a line (about 0.7);
- a code keyword class / interface / struct at the start of a line or after
  public/static (about 1.1), and C preprocessor #define (about 1.0);
- a dot leader '··' (about 0.33).
Everything else is predicted as 0; the small diffuse remainder is not modelled."""
READS = ()

DECL = {"class", "interface", "struct"}


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    prev = prefix.token_strings[-2] if len(prefix) > 1 else ""
    value = 0.0
    if tok == "://" and prev.strip() in ("http", "https"):
        value = 2.1
    elif tok == "{" and prev in ("begin", "end"):
        value = 1.15
    elif tok == '{"' and prev.endswith("\n"):
        value = 0.7
    elif tok.strip() in DECL and (prev.endswith("\n") or prev.strip() in ("public", "static")):
        value = 1.1
    elif tok.strip() == "#define":
        value = 1.0
    elif tok == "··":
        value = 0.33
