"""Layer-1 MLP down-projection, component 3049: a document-opening detector.

In plain terms: this component is almost silent everywhere inside a document. Its
only sizeable activity is on the first token of a document, the token that opens
a packed row or follows an end-of-document boundary inside a row. There the model
has no context yet, and the component's output is set mostly by what kind of token
opens the document:

- a capitalised word (e.g. "How", "Learn") pushes it up;
- a lowercase fragment (e.g. "kl", " bl") pushes it up a little;
- code punctuation (brackets, braces, slashes, #, quotes, =) pushes it down;
- ordinary mid-document tokens get 0.

Only these coarse classes are used. Token identity explains more (a per-token
table reaches about 0.2 variance explained on held-out text, but it is a lookup
with no concept behind it), and the rest of the component's variance is diffuse
and context-dependent, so this program explains only a small share of it.
"""

READS = ()

CODE_PUNCT = set("{}();=<>[]#/\\\"'")


def _opens_document(prefix):
    """True at a row's first token and at the first token after a document change."""
    if prefix.position == 0:
        return True
    return prefix.document_ids[-1] != prefix.document_ids[-2]


def _opener_value(token):
    """Activation at a document's first token, from the token's coarse class."""
    text = token.strip()
    value = -0.097
    if text[:1].isupper():
        value += 0.253
    elif text[:1].islower():
        value += 0.103
    if any(c in CODE_PUNCT for c in token):
        value -= 0.145
    return value


def step(carry, prefix, upstream):
    if not _opens_document(prefix):
        return carry, 0.0
    return carry, _opener_value(prefix.token_strings[-1])


def main():
    """Print the program's prediction for a few example openers, to read it by eye."""
    for token in ["How", "using", "kl", " bl", "{", " the"]:
        print(repr(token), round(_opener_value(token), 3))


if __name__ == "__main__":
    main()

