"""Recognize declaration headers, not their meaning.

Large negative values mark C-family return/type words and the punctuation
finishing those types. Indentation, access modifiers, and a preceding blank
line distinguish declarations from expressions. Document-opening code words
have separate responses; public/static and main have positive exceptions.
Ordinary prose is near zero. The line parser is only a heuristic: it tracks
recent line context, resets at document boundaries, and never looks ahead
to a name.
"""
import re

READS = ()

# Strength at a fresh C/C++ line, and after a public access modifier.
TYPE_STRENGTH = {
    'int': (3.6, 3.6),
    'bool': (5.7, 4.8),
    'boolean': (1.0, 5.5),
    'void': (3.4, 0.55),
    'double': (2.5, 3.8),
    'float': (0.6, 1.4),
    'char': (1.2, 1.2),
    'long': (0.8, 3.0),
    'short': (0.8, 1.0),
    'byte': (0.5, 1.0),
    'String': (0.2, 5.0),
    'string': (0.3, 2.0),
}
GENERIC_TYPES = set('List Map Set Collection IEnumerable Optional Result Pair '
                 'Array Vector vector map set pair optional shared_ptr unique_ptr'.split())
BOXED = set('Integer Long Short Byte Character Double Float Boolean'.split())
MODIFIERS = set('public protected private internal static final abstract override '
                'virtual async sealed readonly synchronized extern inline const '
                'volatile unsafe new partial export signed unsigned'.split())
MODIFIER_PREFIX = re.compile(r'^\s*(?:(?:' + '|'.join(MODIFIERS) + r')(?:\s+|$))+')
ANNOTATIONS = re.compile(r'^(?:\s*@\w+(?:\([^)]*\))?\s*)+')
DOCUMENT_OPENERS = {
    'int': -9.66,
    'string': -8.28,
    'def': -9.4,
    'package': -5.63,
    'class': -4.39,
    'function': -3.64,
    'theorem': -2.06,
    'const': -1.92,
    'import': -1.54,
    'export': -1.94,
    'using': 1.48,
}


def strength(word):
    if word in TYPE_STRENGTH:
        return TYPE_STRENGTH[word]
    if word in GENERIC_TYPES:
        return (0.1, 3.8)
    if word in BOXED:
        return (0.2, 3.0)
    if re.fullmatch(r'u?int(?:8|16|32|64)(?:_t)?', word):
        return (2.0, 2.0)
    if word.isascii() and word.isidentifier() and word[0].isupper():
        return (0.0, 0.75)
    return (0.0, 0.0)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    _, line, last_line, previous = (doc, '', '', '') if first else carry
    text = prefix.token_strings[-1]
    word = text.strip()
    before = re.sub(r'^\s*\d+\t', '', line)
    before = ANNOTATIONS.sub('', before)
    match = MODIFIER_PREFIX.match(before)
    modifiers = set(before[:match.end()].split()) if match else set()
    body = before[match.end():] if match else before.lstrip()
    fresh = not last_line.strip() or last_line.rstrip().endswith(('}', '*/', '>'))
    c_type, method_type = strength(word)
    value = 0.0

    if first and not text.startswith((' ', '\t')):
        value = DOCUMENT_OPENERS.get(word, 0.0)
        if word == '#':
            value = -3.75
        elif word.startswith('#'):
            if set(word) == {'#'}:
                value = -3.0
            else:
                value = -1.7 if word.startswith('#!') else -0.7
        elif word.startswith(('"""', "'''")):
            value = -5.3
        elif word.startswith(('/*', '//')):
            value = -2.5
        elif word.isupper() and word.lower() in TYPE_STRENGTH:
            value = -4.35
    elif match and not body:
        if 'public' in modifiers:
            value = -method_type
        elif modifiers & {'private', 'protected'}:
            value = -0.5 * method_type
        else:
            value = -c_type * (1.0 if fresh else 0.3)
        if modifiers & {'final', 'readonly'}:
            value *= 0.2
    elif not before.strip():
        indented = bool(before) or text.startswith((' ', '\t'))
        value = -c_type * (0.2 if indented else 1.0 if fresh else 0.2)
    elif word == 'void':
        value = -0.6

    # Punctuation extending a leading type, before any parameter list.
    head = body.split('<')[0].split('::')[0].strip()
    type_like = head in TYPE_STRENGTH or head in GENERIC_TYPES or head == 'std'
    type_like |= bool(head and head[0].isupper() and head.isidentifier())
    header = not any(ch in body for ch in '(){}=;')
    access = bool(modifiers & {'public', 'private', 'protected'})
    if header and (type_like or match):
        if word and set(word) <= set('>[],?') and '<' in body:
            is_class = body.startswith(('class ', 'interface '))
            if 'public' in modifiers and not is_class:
                value = -3.5
            else:
                value = -1.5 if access else -0.8
        elif '[]' in word and set(word) <= set('[]'):
            value = -3.5 if access else -0.5
        elif word and set(word) <= set('*&') and re.fullmatch(r'\w[\w:]*[ *&]*', body):
            value = -2.5 if fresh and not before.startswith(' ') else -0.5
        elif word == '::' and head == 'std':
            value = -1.5
        elif not word and '\n' in text and body.strip() in TYPE_STRENGTH:
            value = -TYPE_STRENGTH[body.strip()][0]
        elif word in {'~', '::~'}:
            value = -4.0
    if body == 'TEST' and word in {'_F', '_P'}:
        value = -5.5
    if word == 'main' and (previous in TYPE_STRENGTH or previous in {'func', 'fn'}):
        value = 3.5 if previous in {'func', 'fn'} else 0.8
    if word == 'public':
        value = 0.35
    elif word == 'static':
        value = 0.3
    elif word == '@Override':
        value = 0.8
    elif word.startswith('*/'):
        value = -0.6
    elif word in {'<|endoftext|>', '<|im_end|>'}:
        value = -0.07

    if '\n' in text:
        parts = (line + text).split('\n')
        last_line, line = parts[-2:]
    else:
        line = (line + text)[-300:]
    return (doc, line, last_line, word or previous), value

