"""layers.1.mlp.down_proj:3050: a "declaration header" detector, mostly negative.

The component is quiet almost everywhere. It goes strongly negative on the type word that opens a
code declaration, where a method, field or C function's return type is written:
  - a type name right after an access/declaration modifier: "public String getRol()",
    "static int x", "private List<Game>", "extern int ...", "typedef int ...";
  - a type name at the start of an unindented line (C/C++ function definitions, "bool fs_visitor::");
  - the '>' that closes a generic type in such a header: "public List<Game>", "template <typename T>";
  - "package", "#" or "##" opening a new document, and gtest's TEST_F.
It is also a little negative on the end of a doc comment ("*/") just before a declaration.
It is weakly positive on the function name "main" after its return type ("int main", "func main").
Everything else predicts 0.
"""

READS = ()

# How strongly each type name opens a declaration right after a modifier (negative).
MODIFIED = {"boolean": -4.5, "bool": -4.5, "List": -4.0, "String": -4.0, "Optional": -4.5,
            "int": -3.0, "uint": -3.0, "double": -3.0, "string": -3.0, "float": -2.0,
            "Map": -2.5, "long": -2.0, "char": -2.0, "Collection": -3.0, "Set": -2.0,
            "Result": -2.0, "Object": -1.5, "void": -0.7, "def": -0.7}

# The same type names opening an unindented line, e.g. "bool fs_visitor::" or "void clear()".
LINE_START = {"bool": -4.0, "void": -2.5, "int": -2.0, "float": -1.5, "string": -1.2, "double": -1.0,
              "char": -0.8, "package": -4.0, "def": -0.5, "class": -0.5}

MODIFIERS = {"public", "private", "protected", "static", "override", "internal", "virtual",
             "abstract", "extern", "inline", "typedef", "async"}
STOP = {";", "{", "}", "(", ")", "=", ""}


def generic_header(toks):
    """True if the '>' just read closes a '<' that opens a generic type in a declaration header."""
    for j in range(len(toks) - 2, max(-1, len(toks) - 10), -1):
        t = toks[j].strip()
        if t == "<":
            return any(toks[k].strip() in MODIFIERS or toks[k].strip() == "template"
                       for k in range(max(0, j - 4), j))
        if t in STOP:
            return False
    return False


def step(carry, prefix, upstream):
    toks = prefix.token_strings
    cur = toks[-1].strip()
    doc_start = len(prefix) < 2 or prefix.document_ids[-2] != prefix.document_ids[-1]
    prev = "\n" if doc_start else toks[-2]
    if doc_start and cur in ("package", "#", "##"):
        return carry, -4.0
    if cur == "TEST_F" or (prev.strip() == "TEST" and cur == "_F"):
        return carry, -5.0
    if cur in (">", ">>") and generic_header(toks):
        return carry, -3.0
    if toks[-1] == " */\n":
        return carry, -0.8
    if cur == "main" and prev.strip() in ("int", "void", "func", "fn"):
        return carry, 1.5 if prev.strip() in ("int", "void") else 2.5
    if prev.strip() in MODIFIERS:
        if cur in MODIFIED:
            return carry, MODIFIED[cur]
        if cur[:1].isupper():
            return carry, -0.5
        return carry, 0.0
    if doc_start or "\n" in prev or prev.endswith("<|endoftext|>"):
        return carry, LINE_START.get(cur, 0.0)
    if prev.strip() == "" and cur in LINE_START:
        return carry, 0.3 * LINE_START[cur]
    return carry, 0.0

