READS = ()

COPULAS = set('am is are was were be been being become becomes became'.split())
PREPOSITIONS = set('for to in of by on at through during over into'.split())
QUANTITIES = set(
    'one two three few little bit lot many any some nothing anything'.split()
)
MODIFIERS = set('much even far still'.split())
MUCH_PHRASES = set('how so too very pretty'.split())
