        if before in PREPOSITIONS:
            value = 1.8
        elif before in {'a', 'an'}:
            value = 1.5
        elif (before in COPULAS or before in MODIFIERS
              or before in {'the', 'or', 'no'}):
            value = 0.23
        elif before in QUANTITIES or before.isdigit():
            value = 0.03
        elif before in {'and', 'with'}:
            value = 0.85
        else:
            value = 0.6
    elif s == ' much':
        if before in MUCH_PHRASES:
            value = 0.0
        elif before in {'as', 'not', 'no'}:
            value = 0.3
        elif before in PREPOSITIONS:
            value = 2.7
        elif before in COPULAS:
            value = 1.3
        elif before in {'a', 'an', 'and', 'with'}:
            value = 2.0
        else:
            value = 1.55
    elif w in {'More', 'Much'}:
        value = 0.3
    elif w in {'更', '更加', '更多', '較', '较'}:
        value = 0.8
    elif s.startswith('.') and len(s) > 1 and set(s[1:]) <= DASHES:
        if before.isdigit() or (prev.strip().isupper() and len(before) > 1):
            value = -3.8
        elif prev.startswith('.'):
            value = -0.5
        else:
            value = -2.5
    elif w and w[0] in DASHES and prev.strip(' \"\'”’') == '.':
        value = -1.5 if prev == '.' else -0.8
    elif w == '—':
        value = -0.15 if not s.startswith(' ') else 0.0
    elif w == '··':
        value = 0.82 if prev == '··' or not prev else 0.1
    return (doc, s), value

