            elif before.isspace() and not after:
                value = spaced_quote(q, previous, recent)
            elif before and any(c in '([{' for c in before) and not after:
                value = -0.78 if q == '"' else -0.65
                if '\n' in previous:
                    value = -1.45 if q == '"' else -0.85
            elif q == '"' and recent.endswith(('r', 'r#')) and '#' in s:
                value = -1.8  # Rust raw-string opening delimiter
            elif before and '=' in before and not after:
                value = -1.1 if q == '"' else -0.7
            elif before and '\\' in before and not after:
                value = -1.25 if before[0].isspace() else -0.4
            elif not before and not after:
                value = -0.15 if q == '"' else -0.03
                if previous and previous[-1].isspace():
                    value = -1.8 if q == '"' else -1.1
                if previous and previous[-1] in '(（【：' and q != "'":
                    value = -1.1
                # Unspaced quotations are common in non-Latin writing.
                bit = 1 if q == '"' else 2
                if (q != "'" and previous and previous[-1].isalpha()
                        and not previous[-1].isascii() and not parity & bit):
                    value = -1.55
            elif not before and after[0].isalpha():
                if q == '"' or (q == "'" and after[0].isupper()):
                    value = -1.3
            elif before.isspace() and after and after[0] != q:
                value = -0.85
            elif before.endswith(':') and not after:
                value = -0.75
            elif before and not after:
                value = -0.15
        elif s.startswith(' ') and s.strip() in ('$', '*', '**'):
            value = {'$': -0.25, '*': -0.1, '**': -0.5}[s.strip()]
    if position == 0 and value < -0.3:
        value = 0.0
    parity ^= (s.count('"') % 2) | ((s.count('`') % 2) << 1)
    return (doc, s, (recent + s)[-160:], position + 1, parity), value

"""Approximate a year-like number completion signal.

Respond at the fourth consecutive single ASCII-digit token, using calendar
year ranges rather than attempting to parse the surrounding text as a date.

Recent historical years give a large positive value, old or far-future years
less. Numbers attached directly to punctuation or letters are downweighted,
as are round years when the base response is large. Smaller rules handle
split indefinite words and partitive phrases. Opening spaces and an initial
``Title:`` field are special cases.
"""
READS = ()


def year_response(year):
    if 1500 <= year < 1800:
        return 0.17
    if 1800 <= year < 1850:
        return 0.50
    if 1850 <= year < 1930:
        return 0.85
    if 1930 <= year < 1970:
        return 1.25
    if 1970 <= year < 2000:
        return 1.60
    if 2000 <= year < 2020:
        return 1.43
    if 2020 <= year < 2040:
        return 0.97
    if 2040 <= year < 2100:
        return 0.35
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        run, spaced, prev, prev2, position = '', True, '', '', 0
    else:
        _, run, spaced, prev, prev2, position = carry
    token = prefix.token_strings[-1]
    value = 0.0
    if len(token) == 1 and '0' <= token <= '9':
        if not run:
            spaced = not prev or prev[-1].isspace()
        run += token
        if len(run) == 4:
            value = year_response(int(run))
            if value > 0.4:
                if not spaced:
                    value -= 0.20
                if token == '0':
                    value -= 0.15
    else:
        run = ''

    before = prev.strip().lower()
    before2 = prev2.strip().lower()
    word = token.strip().lower()
    if before in {'some', 'every', 'any', 'no'}:
        if word in {'one', 'body', 'thing', 'where'}:
            value = 0.65
            if word == 'one':
                one_values = {
                    'some': 0.95, 'every': 0.33, 'any': 0.20, 'no': 0.18
                }
                value = one_values[before]
    if before == 'else' and word == 'where':
        value = 1.0
    if word == 'one' and before in {'each', 'which'}:
        value = -0.33
    if word == 'of':
        if before == 'one' and before2 in {'each', 'which', 'every', 'any'}:
            value = -0.65
        elif before == 'amount' and before2 in {'any', 'no'}:
            value = -0.8 if before2 == 'any' else -1.4
        elif before == 'number' and before2 == 'any':
            value = -0.43

    if position == 0:
        if token == ' ':
            value = 1.12
        elif token == 'Title':
            value = 0.70
    elif position == 1 and prev == 'Title' and token == ':':
        value = -8.29
    return (doc, run, spaced, token, prev, position + 1), value

programs.haiku:
"""Year-digit detector for layers.1.mlp.down_proj:3055.

The component's job is to mark the end of a year written in digits. It fires on the
last digit of a four-digit number that reads as a year in running text (for example
"in 2010", "(1744", "since 1998"). The strength depends on the year: near zero before
1500, weak in the 1500s to 1700s, moderate in the 1800s and early 1900s, strongest for
1930 to 2019, and weaker again in the 2020s. Numbers that are not years (1203, 2397,
part numbers, and so on) stay near zero. The earlier digits of the year are near zero,
and so is most other text. A run of two middle dots (··), as in table-of-contents
leaders, also fires, at about the same level as a strong year.

Program: at each token, look at the last four tokens. If they are four digits of one
document that begin a number (no digit before them), and the number starts 15 to 20,
predict the year's level. Other positions predict 0.
"""

READS = ()

DOTS = "··"


def year_level(year):
    """Typical activation for a four-digit year, by its century and decade."""
    if year < 1500 or year > 2029:
        return 0.0
    if year < 1700:
        return 0.15 if year < 1600 else 0.25
    if year < 1800:
        return 0.3
    if year < 1900:
        return 0.7
    if year < 1930:
        return 0.9
    if year < 1950:
        return 1.2
    if year < 2020:
        return 1.5
    return 0.95


def _is_digit(token):
    return len(token) == 1 and token in "0123456789"


def step(carry, prefix, upstream):
    strings = prefix.token_strings
    if strings[-1] == DOTS:
        return None, 0.96
    if len(strings) < 4:
        return None, 0.0
    last4 = strings[-4:]
    if not all(_is_digit(s) for s in last4):
        return None, 0.0
    if len(set(prefix.document_ids[-4:])) != 1:
        return None, 0.0
    if len(strings) >= 5 and _is_digit(strings[-5]):
        return None, 0.0
    return None, year_level(int("".join(last4)))

programs.sol:
"""Newspaper names, publication titles, and the web addresses used to cite them.

Strong responses occur on title completions such as USA Today, Washington
Post, or Associated Press. Ambiguous title words need supporting context.
Press/news releases and URL markers give smaller responses; documentation
and source-code hosting get negative ones. Everything else defaults to zero.
"""
import re
import inflect

READS = ()
_numbers = inflect.engine()
NUMBER_WORDS = {_numbers.number_to_words(n).lower() for n in range(21)}
del _numbers

# Familiar publication titles, indexed by their last two words.
TITLE_COMPLETIONS = {
    ('USA', 'Today'): 13.0,
    ('Psychology', 'Today'): 10.0,
    ('Mississippi', 'Today'): 6.0,
    ('Washington', 'Post'): 11.0,
    ('Huffington', 'Post'): 12.0,
    ('York', 'Post'): 5.5,
    ('Financial', 'Times'): 10.0,
    ('Angeles', 'Times'): 10.0,
    ('Petersburg', 'Times'): 10.0,
    ('York', 'Times'): 7.5,
    ('Associated', 'Press'): 8.5,
    ('Free', 'Press'): 4.5,
    ('Canadian', 'Press'): 4.0,
    ('Street', 'Journal'): 9.0,
    ('Science', 'Daily'): 6.0,
    ('Daily', 'Tribune'): 9.5,
    ('Morning', 'Herald'): 8.0,
    ('Miami', 'Herald'): 7.0,
    ('Boston', 'Herald'): 6.0,
    ('Boston', 'Globe'): 6.5,
    ('Daily', 'Mail'): 6.0,
    ('Daily', 'Star'): 6.0,
    ('Daily', 'Express'): 5.0,
    ('Indian', 'Express'): 5.0,
    ('Evening', 'Standard'): 6.5,
    ('Weekly', 'Digest'): 3.5,
    ('Business', 'Insider'): 4.0,
    ('Sports', 'Illustrated'): 5.0,
    ('Scientific', 'American'): 3.5,
    ('Hollywood', 'Reporter'): 3.5,
}
PAPER_WORDS = set('Herald Tribune Chronicle Sentinel Gazette Courier '
                  'Inquirer Enquirer'.split())
OTHER_TITLES = set('Mirror Globe Review Weekly Digest Monthly Record '
                   'Bulletin Independent Atlantic'.split())


def response(before, token):
    word = token.strip()
    match = re.search(r'''([A-Za-z0-9]+)[\s'"“”‘’(\-]*$''', before)
    last = match[1] if match else ''
    pair = TITLE_COMPLETIONS.get((last, word))
    if pair is not None:
        return pair
    if word == 'Times' and token[:1].isspace():
        if last.isdigit() or last.lower() in NUMBER_WORDS | {'of', 'many', 'several'}:
            return 0.0  # counts/repetition, rather than a newspaper title
        return 6.5 if last.lower() == 'the' else 4.0
    if word == 'Daily':
        return 4.5 if last.lower() == 'the' else (2.0 if before else 0.0)
    if word == 'Telegraph':
        return 8.0
    if word in {'Guardian', 'Observer'}:
        return 5.5 if last.lower() == 'the' and token[:1].isspace() else 0.0
    if word in PAPER_WORDS:
        return 4.0 if last.istitle() and token[:1].isspace() else 0.0
    if word in OTHER_TITLES:
        if word == 'Weekly' and last in {'Us', 'US', 'LA', 'Orlando'}:
            return 4.5
        return 2.0 if last in {'The', 'Daily', 'Sunday', 'Saturday', 'London'} else 0.0
    if word == 'Mail' and before.endswith('Globe and'):
        return 3.5
    if word == 'Post':
        return 1.3 if last.lower() == 'the' else 0.0
    if word == 'Sun':
        return 1.5 if last == 'The' else 0.0
    if word == 'Politico':
        return 5.0
    if word == 'Reuters':
        return 1.8
    if word in {'BBC', 'CNN', 'NBC', 'CNBC', 'MSNBC'}:
        return 0.8
    if word == 'News':
        return 3.5 if last in {'Daily', 'Morning'} else (0.8 if before else 0.0)
    if word == 'Associated':
        return 3.5 if last.lower() == 'the' else 0.2
    if word in {'Press', 'Journal'}:
        return 0.4
    if word == 'Show' and last in {'Daily', 'Morning'}:
        return 3.5
    if word.lower() in {'release', 'releases'}:
        return 3.8 if last.lower() in {'press', 'news'} else 0.0
    if word in {'Magazine', 'magazine', 'newspaper', 'newsletter'}:
        return 1.8 if word == 'Magazine' else 0.3
    if word == 'New' and last.lower() == 'the':
        return 0.6
    if word == 'www':
        return 1.9 if before.endswith('https://') else (
            1.4 if before.endswith('http://') else 0.0)
    if word in {'img', 'docs'} and before.endswith('://'):
        return 3.0 if word == 'img' else -1.9
    if word == '.wikipedia':
        return 1.3
    if word in {'.com', '.org', '.net', '.uk'}:
        if before.endswith(('github', 'gitlab')):
            return -0.6
        url = re.search(r'''(?:https?://|www\.)[^\s<>"']*$''', before)
        return 0.9 if url else 0.1
    # Chinese newspaper suffixes and news websites.
    if word in {'日报', '日報', '晚报', '晚報', '新华网', '中新网'}:
        return 6.5
    if word in {'时报', '時報'}:
        return 8.5
    if word in {'报', '報'}:
        return 7.0 if re.search(r'《[^》\n]{1,12}$', before) else 1.3
    if word == '网':
        return 4.0 if before.endswith(('新浪', '新闻', '门户')) else 0.5
    if word in {'在线', '在線'}:
        return 1.7
    if word == '》' and before.endswith(('报', '報')):
        return 2.0
    if not token[:1].isspace():
        joined = (before + token).lower()
        if joined.endswith('huffingtonpost'):
            return 12.0
        if joined.endswith(('nytimes', 'koreatimes', 'indiatimes',
                            'citizen-times', 'courier-journal')):
            return 6.5
        if joined.endswith(('newsweek', 'newscient', 'britannica')):
            return 4.5
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    before = '' if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    return (doc, (before + token)[-140:]), response(before, token)

programs.haiku:
"""layers.1.mlp.down_proj:3057 -- the "list separator" component.

What it does: it goes strongly negative on the comma or conjunction ("," "and" "or" "und"
"和" "etc" ...) that continues or closes a list of short items, such as the "and" in
"music, television and radio". It is near zero elsewhere: on ordinary words, on the first
separator of a sentence, and on conjunctions that join whole clauses or adjectives.

How the prediction is built, one step per token:
  * A separator counts only once the sentence already holds an earlier separator, so the
    first item of a list is not marked.
  * The size depends on how many tokens the item just before it has (the words since the
    previous separator): 1-2 words is strongest, fading to nothing by about 6 words.
  * It is weaker when the previous separator was "and"/"or" rather than a comma, when the
    item holds a preposition or verb (a phrase or clause, not a bare noun), when the item
    is a discourse adverb ("however", "then"), or when only one comma has come so far.
  * Sentences reset at . ! ? ; : and newlines; documents reset everything.

Only the separator's sign and rough size are predicted; everything else is 0.
"""

READS = ()

# Separators: commas, and conjunctions in several languages ("and", "und", "和", ...).
COMMAS = {",", "，", "、", " ,"}
WORD_CONJUNCTIONS = {"and", "or", "und", "et", "y", "e", "og", "och", "dan", "atau", "ou",
                     "или", "и", "etc", "và", "eller", "oder", "veya", "ve", "ili", "&"}
CJK_CONJUNCTIONS = {"和", "与", "或", "及", "以及", "等"}
# Prepositions, copulas and relative words: their presence marks a phrase or clause.
PHRASE_WORDS = {"of", "to", "in", "with", "for", "on", "by", "at", "from", "is", "was", "are",
                "be", "were", "that", "which", "who", "as", "it"}
# Discourse adverbs that sit between commas ("However, ..."): not list items.
ADVERBS = {"however", "therefore", "then", "actually", "also", "indeed", "instead", "thus",
           "hence", "so", "yet", "still", "now", "here", "there", "well", "but", "not", "no",
           "yes", "say", "again", "finally", "first", "second", "today", "perhaps", "maybe",
           "otherwise"}
ENDERS = {".", "!", "?", ";", ":"}

# Size of the value by the number of words in the item before the separator.
SIZE = {0: 1.0, 1: 4.0, 2: 4.0, 3: 3.0, 4: 2.0, 5: 1.0}


def is_separator(tok):
    if tok in COMMAS or tok in CJK_CONJUNCTIONS:
        return True
    # a word joined to a leading space, such as " and", " OR", " etc"
    return tok[:1] == " " and tok.strip().lower() in WORD_CONJUNCTIONS


def strength(item_len, has_phrase_word, after_comma, commas_so_far, last_word):
    s = SIZE.get(item_len, 0.0)
    if last_word in ADVERBS:
        s *= 0.2
    if has_phrase_word:
        s *= 0.4
    if not after_comma:
        s *= 0.1
    if commas_so_far < 2:
        s *= 0.7
    return s


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    docs = prefix.document_ids
    if carry is None or (len(docs) > 1 and docs[-1] != docs[-2]):
        carry = (0, 0, False, 0, False, "")
    # seps: separators so far in the sentence; commas: commas so far; prev_comma: the last
    # separator was a comma; n: words in the current item; phrase: item has a phrase word
    seps, commas, prev_comma, n, phrase, last = carry
    value = 0.0
    if is_separator(tok):
        if seps >= 1:
            value = -strength(n, phrase, prev_comma, commas, last)
        comma = tok in COMMAS
        carry = (seps + 1, commas + comma, comma, 0, False, "")
    elif tok.strip() in ENDERS or "\n" in tok:
        carry = (0, 0, False, 0, False, "")
    else:
        word = tok.strip().lower()
        carry = (seps, commas, prev_comma, n + 1, phrase or word in PHRASE_WORDS, word)
    return carry, float(value)

programs.sol:
"""A spelling-fragment detector centered on P and PAL.

PAL/PAV/PAW/PILL/PANT-like pieces are negative, especially when P and AL
are split across tokens. Longer fragments give weaker responses. Short
P-consonant clusters and the NPX/PNPM command spellings are positive.
These are local spelling rules, not semantic classifications of words.
"""
import regex
from anyascii import anyascii

READS = ()
ALPHABETS = regex.compile(r'[\p{Latin}\p{Greek}\p{Cyrillic}]+')


def spelling(s):
    if not s.isascii():
        s = ALPHABETS.sub(lambda m: anyascii(m[0]), s)
    return s.lower().replace("'", '')


def predict(s, previous):
    a, p = spelling(s), spelling(previous)
    w = a.lstrip(' \t\n_./-')
    scale = 1.0 if s.isascii() else 0.65
    joined = a[:1].isalpha()

    if joined and p.endswith('p') and not p.endswith('cip'):
        if a.startswith('al') and len(a)<=5:
            strength = 5.5 if len(a)==2 else 3.3
            if p.endswith('mp'):
                strength *= 0.4
            return -strength * scale * 0.65 ** max(0,len(a)-3)
        if a.startswith(('av','aw')) and not a.startswith('awn'):
            return -3.0 * scale * 0.8 ** max(0,len(a)-2)
        if a.startswith(('ant','and')):
            return -1.8 * scale * 0.7 ** max(0,len(a)-3)
        if len(a)<=3 and a.startswith(('ah','ap','ab','aj')):
            return -1.0 * scale
        if a.startswith('il') and len(a)<=5:
            return -0.7 * scale
        if s.isascii() and a in ('ci','tr','ct'):
            return 2.0
        if s.isascii() and a in ('x','z'):
            return 1.0

    if 'pal' in w and len(w)<=8:
        before, _, tail = w.partition('pal')
        strength = scale * 0.7 ** len(before) * 0.75 ** len(tail)
        if w in ('pale','pall'):
            strength *= 0.45
        if w=='pal' and s[:1]=='p' and p[-1:].isalpha():
            strength *= 1.2
        return -4.1 * strength
    if w.startswith('paw') and not w.startswith('pawn'):
        return -2.7 * scale
    if w.startswith('pav'):
        return -1.1 * scale
    if w.startswith('pill'):
        return -1.5 * scale * 0.7 ** max(0,len(w)-4)
    if w.startswith(('pant','pand')):
        return -1.0 * scale * 0.6 ** max(0,len(w)-4)
    if joined and a=='px' and p.endswith('n') and s.islower():
        return 3.0
    if joined and a=='pm' and p.endswith('pn'):
        return 3.0
    if joined and a.startswith('p') and len(a)<=3:
        if p.endswith('al') and len(p.strip())<=4:
            return -1.8 * scale
    return 0.0


def step(carry, prefix, upstream):
    doc, s = prefix.document_ids[-1], prefix.token_strings[-1]
    prev = carry[1] if carry is not None and carry[0]==doc else ''
    return (doc, s), predict(s, prev)

"""Short phrase responses, with a strong boost at the start of a document.

Question words usually receive negative values; following auxiliaries can
produce positive pulses, especially in document-opening questions.  Some first-person
and prepositional openings behave similarly.  Conjunction responses use
nearby common French, Italian or Portuguese words as a crude prose-versus-
abbreviation test, with stronger responses early in a document.
Everything else stays near zero, apart from a few small thinking-phrase rules.
These are approximate phrase rules, not a complete account of the component.
"""
from wordfreq import top_n_list

READS = ()
ENGLISH = set(top_n_list('en', 500))
FRENCH = set(top_n_list('fr', 100)) - ENGLISH
ROMANCE = (set(top_n_list('it', 100)) |
           set(top_n_list('pt', 100))) - ENGLISH


def nearby_words(prefix, pos, words):
    n = min(pos, 32)
    return sum(s.strip().lower() in words
               for s in prefix.token_strings[-n-1:-1]) if n else 0


# Grammatical opening words, followed by their auxiliary or article.
OPENINGS = {
    'What': {' is': 5.32, ' are': 5.24, ' do': 3.63, ' can': 2.31},
    'How': {' do': 5.44, ' does': 4.21, ' can': 4.04, ' is': 3.51},
    'I': {' have': 2.22, "'m": 1.85, '’m': 1.24, "'ve": 1.39},
    'In': {' a': 1.08, ' an': 1.30},
    'When': {' I': 0.53},
    'Is': {' it': 2.23},
}
FIRST_WORD = {'What': -0.72, 'How': -0.41, 'I': -0.55,
              'When': -0.41, 'To': -0.71}
AUXILIARIES = {'is', 'are', 'was', 'were', 'do', 'does', 'did',
               'can', 'could', 'would', 'should', 'will', 'have', 'has'}
QUESTION_WORD = {'what': -0.13, 'how': -0.12, 'why': -0.17,
                 'who': -0.10, 'which': -0.025, 'where': -0.02}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    s = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        pos, prev, before = 0, '', ''
    else:
        _, pos, prev, before = carry
    w, p = s.strip().lower(), prev.strip().lower()
    value = QUESTION_WORD.get(w, -0.002)

    if p == 'how' and w in AUXILIARIES:
        direct = prev.strip() == 'How'
        if w == 'do':
            value = 0.30 if direct else 0.19
        elif w in {'does', 'did'}:
            value = 0.20 if direct else -0.04
        else:
            value = 0.09 if direct else 0.0
    elif prev.strip() == 'What' and w in AUXILIARIES:
        value = 0.08
    elif p == 'why' and w in AUXILIARIES:
        value = 0.08
    if p == 'me' and w == 'think':
        value = 0.25
    if p == 'to' and w == 'know':
        value = 0.09
    if p == 'make' and w == 'sure':
        value = 0.04 + 4.0 / (pos + 8)
    if p == 'and' and w in AUXILIARIES:
        value = -0.15 + 3.3 / (pos + 8)
    if prev == ',' and w == 'and':
        value = -0.045
    if s == ' et':
        french = nearby_words(prefix, pos, FRENCH) >= 4
        value = 0.04 + 7.0 / (pos + 16) if french else 0.01
        if prev == ',':
            value = (0.22 + 25.0 / (pos + 32) if french
                     else 0.03 + 8.0 / (pos + 8))
    if s == ' e':
        evidence = nearby_words(prefix, pos, ROMANCE)
        value = 0.05 if evidence >= 4 else -0.01
        if prev == ',':
            value = (0.40 + 7.0 / (pos + 16) if evidence >= 4
                     else 0.20 if evidence >= 2 else -0.02)
    if s == ' und' and prev == ',':
        value = 0.20 + 9.7 / (pos + 8)

    if pos == 0:
        value = FIRST_WORD.get(s, value)
    if pos == 1:
        value = OPENINGS.get(prev, {}).get(s, value)
        if prev == 'I' and w in {'found', 'feel', 'wanted', 'wrote'}:
            value = 0.9
        if prev == 'To' and w in {'find', 'calculate'}:
            value = 1.15
    if pos == 2:
        if before == 'How' and prev == ' do' and s == ' you':
            value = 3.12
        if before == 'How' and prev == ' can' and s == ' I':
            value = 1.10
        if before == 'What' and prev in {' is', ' are'} and s == ' the':
            value = 1.02 if prev == ' is' else 1.64
        if before == 'I' and prev == ' have' and s == ' a':
            value = 1.02
    return (doc, pos + 1, s, prev), value

programs.haiku:
"""Question openers and their follow-up word, plus foreign conjunctions after a comma.

The component reads the start of a user's question or first-person sentence:
- the word right after a document-opening question word or 'I' gets a strong positive value
  ('How [do] you', 'What [is]', 'I [have]', 'I [m]'); the opener itself is slightly negative;
- a conjunction such as 'et', 'und', 'og', 'e' that follows a comma (a non-English clause or
  list joiner) gets a moderate positive value.
Everything else predicts 0.
"""

READS = ()

OPENERS = {"How", "What", "Where", "Who", "Why", "When", "Which", "Can", "Do", "Is", "I"}
AUX_AFTER_OPENER = {" do", " is", " can", " are", " have", " does", " should", " will", " you", " I", " we", " was"}
AUX_AFTER_I = {" have", "'m", "'ve", " am", " was", " know", " found", " feel", " want", " think"}
FOREIGN_CONJ = {" et", " e", " und", " og", " och", " és", " è", " y", " и"}


def step(carry, prefix, upstream):
    new_doc = prefix.position == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]
    dpos = 0 if new_doc else carry + 1
    cur = prefix.token_strings[-1]
    prev = "" if new_doc else prefix.token_strings[-2]
    value = 0.0
    if dpos == 0 and cur in OPENERS:
        value = -0.5
    elif dpos == 1 and prev == "I" and cur in AUX_AFTER_I:
        value = 2.0
    elif dpos == 1 and prev in OPENERS and cur in AUX_AFTER_OPENER:
        value = 1.0
    elif prev == "," and cur in FOREIGN_CONJ:
        value = 0.3
    return dpos, value

"""Draft 5: p4 plus Slavic-context check for Latin-script 'bez'."""
READS = ()

BEZ_WORDS = {"bez", "без", "бес", "бесп"}            # Slavic 'without' as a whole token
CJK_WITHOUT = {"無", "无", "무", "vô"}                 # Chinese/Japanese, Korean, Vietnamese 'without'
STEMS = ("без", "бес")                               # the Slavic 'bez' spelling
SLAVIC_LETTERS = set("ěřščžůťďňĺľŕąęłżźśćň")         # letters of Czech, Slovak and Polish

def slavic_context(prefix):
    """True if the document so far (last 60 tokens) is written in a Czech/Slovak/Polish-style alphabet."""
    t = len(prefix.token_ids) - 1
    doc = prefix.document_ids[t]
    text = ""
    for i in range(t, max(-1, t - 60), -1):
        if prefix.document_ids[i] != doc:
            break
        text = prefix.token_strings[i] + text
    return any(ch in SLAVIC_LETTERS for ch in text.lower())

def step(carry, prefix, upstream):
    cur = prefix.token_strings[-1].strip().lower()
    prev = prefix.token_strings[-2].strip().lower() if len(prefix.token_strings) > 1 else ""
    if cur == "bez":
        return carry, 11.0 if slavic_context(prefix) else 3.0
    if cur in BEZ_WORDS or cur in CJK_WITHOUT:
        return carry, 8.0
    joined = prev + cur
    for stem in STEMS:
        i = joined.find(stem)
        if 0 <= i < len(prev) < i + len(stem) and i >= len(prev) - 2:
            return carry, 10.0
    if cur.endswith("[^") or (cur.startswith("^") and prev.endswith("[")):
        return carry, 10.0
    return carry, 0.0

"""Layer-1 MLP down-projection unit 3062: a weak, mostly token-driven component.

Its activation is near zero almost everywhere (typical size 0.05). Two readable
patterns carry most of what it does:

1. Document starts. The first token of each document (or of a packed row) has a
   fixed value set by what kind of token it is, because attention cannot yet
   mix in any context there:
   - a common function word with a leading space (" of", " to", " the", " is")
     is positive;
   - a bare single letter with no leading space is negative (the start of a
     word split into pieces);
   - a digit is negative; a whitespace-only token is weakly positive;
   - other word starts are weakly negative (no leading space) or slightly
     negative (leading space, lowercase).
2. The middle dot "··" always gives a positive value (about +0.56).

Everywhere else the prediction is 0. The values are rounded category means
measured on training rows; the per-token spread inside each category is large,
which these rules do not capture.
"""

READS = ()

FUNCTION_WORDS = {
    "to", "of", "the", "a", "an", "is", "be", "was", "by", "also", "in", "on",
    "for", "at", "from", "and", "not", "when", "they", "this", "it", "that",
    "with", "are", "as", "or", "has", "been", "about",
}
MIDDLE_DOT = "··"


def start_value(token):
    word = token.strip()
    leading_space = token.startswith(" ")
    if word == "":
        return 0.12
    if leading_space and word.lower() in FUNCTION_WORDS:
        return 0.28
    if word.isdigit():
        return -0.19
    if word.isalpha() and not leading_space:
        return -0.32 if len(word) == 1 else -0.06
    if word.isalpha():
        return -0.10
    return 0.0


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    n = len(prefix.document_ids)
    at_start = n == 1 or prefix.document_ids[-1] != prefix.document_ids[-2]
    if at_start:
        return carry, start_value(token)
    if token == MIDDLE_DOT:
        return carry, 0.56
    return carry, 0.0

programs.sol:
"""Detect abrupt exits and choices in source code, chiefly return statements.

A statement boundary distinguishes code keywords from prose. Returns are
stronger in conditional branches and tab-indented code, and weaker just
after Python function definitions. Other rules cover ternaries, logical
operators, condition-closing parentheses, export-default and compound
assignments.
A bounded text buffer handles source listings, diffs and escaped newlines.
"""
import re

READS = ()
EXITS = {'return': -7.3, 'break': -5.8, 'continue': -5.6,
         'throw': -5.6, 'raise': -3.8, 'yield': -1.6, 'goto': -1.0}
KEYWORDS = set(EXITS) | {'default', 'case', 'else', '?', ':',
                         '&&', '||', '??', '+=', '-=', '*=', '/='}


def unescape(text):
    return re.sub(r'\\+[ntr]', lambda m: {'n': '\n', 't': '\t',
                  'r': '\r'}[m[0][-1]], text)


def source(old):
    old = re.sub(r'(?m)^[ \t]*\d+[+\-:]?\t', '', old)
    old = re.sub(r'(?m)^([ \t]*)[+\-][ \t]?', r'\1', old)
    old = re.sub(r'(?m)^[ \t]*\d+:[ \t]*', '', old)
    return re.sub(r'/\* \d+ \*/', '', old)


def context(old):
    line = old.rsplit('\n', 1)[-1]
    code = bool(re.search(
        r'[=;{}]|\w[([]|->|'
        r'\b(return|const|let|var|def|func)\b|\bif\s*\(', line))
    if re.search(r'\b(cd|git|npm|pytest|python|bash|echo|SELECT|WHERE)\s', line):
        code = False
    # SQL question marks are parameter placeholders, not choices.
    if re.search(r'\b(select|where)\b', old[-220:], re.I):
        code = False
    blank = not line.strip() or bool(re.fullmatch(r'\s*\d*\s*(?:#|//)?\s*', line))
    boundary = blank or bool(re.search(r'[;{})]\s*$', old))
    boundary |= code and bool(re.search(r':\s*$', old))
    boundary |= bool(re.search(r'\belse\s*$', old))
    return line, blank, boundary, code


def value_for(old, token, choice):
    word = token.strip()
    if word.startswith((')return', ':return')):
        return -9.0
    if word not in KEYWORDS and ')' not in token:
        return 0.0
    old = source(old)
    line, blank, boundary, code = context(old)
    if word in EXITS:
        if re.search(r'(?:@|:|\\)[ \t]*$', line) and not code:
            return 0.1  # documentation's @return or :return
        if not boundary:
            return -1.2 if code else (0.35 if word in {'return', 'break', 'continue'} else 0.0)
        indented = '\t' in line + token or len(line + token) - len((line + token).lstrip()) > 1
        if blank and not indented and not code:
            if not re.search(r'[;{}=]|\b(def|func|if|while|for|else|try|except)\b', old[-200:]):
                return -2.5 if not old else 0.2
        value = EXITS[word]
        if word == 'return':
            clean = re.sub(r'(?m)^[ \t]*#.*$', '', old)
            clean = re.sub(r'(?m)^[ \t]*\d+$', '', clean)
            python = bool(re.search(r'\bdef\b|\bself\.|\bFile "[^\n]*\.py"', clean))
            value += 1.8 * python
            indent = re.sub(r'^\s*\d+\t', '', line + token)
            value -= 1.8 * ('\t' in indent)
            if re.search(r'\bdef\s+[^\n]+:\s*$', clean):
                value += 2.2
            else:
                branch = bool(re.search(
                    r'\b(if|else|except|catch|case)\b[^;{}]*[{}:]?\s*$',
                    clean[-220:]))
                if '{' in clean:
                    head, tail = clean.rsplit('{', 1)
                    branch |= '}' not in tail and bool(re.search(
                        r'\b(if|else|catch|switch)\b[^;{}]*$', head[-200:]))
                value -= 1.8 * branch
                value -= 1.6 * bool(re.search(r'\bif\b[^\n]*\)\s*$', clean[-150:]))
        if '#' in line:
            value *= 0.7
        return value
    if word == 'default' and re.search(r'\bexport\s*$', old):
        return -5.6
    if word in {'case', 'default'} and blank:
        return -1.1
    if word in {'&&', '||', '??'} and code:
        return {'&&': -1.6, '||': -2.1, '??': -2.5}[word]
    if word == '?' and token == ' ?' and (code or blank):
        return -4.8
    if word == ':' and token.startswith(' ') and choice:
        return -7.7
    if word == 'else':
        if re.search(r'\bif\b', line) and ':' not in line and ';' not in line and code:
            return -3.8
        return -0.35 if boundary or code else 0.0
    if ')' in token and not any(c in token for c in ';:{,'):
        matches = list(re.finditer(r'\b(if|while|for|switch|catch)\s*\(', old))
        if matches:
            condition = old[matches[-1].end()-1:]
            depth = condition.count('(') - condition.count(')')
            if depth > 0 and depth + token.count('(') - token.count(')') <= 0:
                return -2.0 if matches[-1][1] == 'if' else -1.3
    if word in {'+=', '-=', '*=', '/='}:
        return -0.5
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    old, choice, last_doc = carry if carry is not None else ('', False, None)
    if doc != last_doc:
        old, choice = '', False
    token = prefix.token_strings[-1]
    value = value_for(old, token, choice)
    if token == ' ?':
        _, blank, _, code = context(source(old))
        choice = code or blank
    elif token.strip() == ':' or ';' in token:
        choice = False
    # Decode only the end of the buffer, where a new escape can be completed.
    text = old[:-8] + unescape(old[-8:] + token)
    return (text[-800:], choice, doc), value

"""Approximate lexical agency/accompaniment responses, not general meaning.

Chinese leading, accompanying, helping and coercing words are positive.
CC-CEDICT supplies these semantic classes. 着/著 is treated using its verb.
Bare chi syllables and repeated middle dots are negative; a document-opening
Title colon also has a negative response. State resets at document changes.
These recurring training patterns are modeled with a few dictionary classes;
most smaller token-specific responses are left unexplained.
"""
from functools import lru_cache
import cedict

READS = ()

@lru_cache(maxsize=16384)
def word_value(word):
    senses = cedict.glosses(word)
    main = next((g for g in senses if 'variant of' not in g), '')
    if main == 'to accompany':
        return 5.8 if len(word) == 1 else 2.3
    if 'leadership' in senses:
        return 2.7
    if main == 'to control':
        return 1.0
    if word.endswith('助'):
        assisting = main.startswith(('to assist', 'to provide assistance'))
        return 1.7 if assisting else 1.0
    if main.startswith('to help'):
        return 0.7
    if main.startswith(('to compel', 'to pressure', 'to force')):
        return 1.1
    if main.startswith('matching'):
        return 1.5
    if 'delegate' in senses or 'on behalf of' in senses:
        return 1.1
    if any(g.startswith(('to wish (sb', 'to congratulate')) for g in senses):
        return 1.5
    if main in {'to lead', 'to command'}:
        return 2.5
    if 'to lead' in senses or 'to command' in senses:
        return 0.7
    if main.startswith(('to encourage', 'to inspire', 'to remind',
                        'to notify', 'to organize', 'to guide', 'to propose')):
        return 0.6
    return 0.0

@lru_cache(maxsize=4096)
def aspect_value(verb):
    senses = cedict.glosses(verb)
    if any(g.startswith(('to display', 'to exhibit', 'to play the role',
                         'to say', 'to speak', 'to experience', 'to sleep'))
           for g in senses):
        return -1.4
    if any(g.startswith(('to carry', 'to hold', 'to lift', 'to pull',
                         'to point', 'to wait')) for g in senses):
        return 1.3
    return max(0.3, word_value(verb))

def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    _, previous, tail, position = (doc, '', b'', -1) if first else carry
    position += 1
    raw = prefix.token_bytes[-1]
    word = prefix.token_strings[-1].strip()
    if word in {'ち', 'チ', '치'}:
        value = -2.7
    elif word in {'り', 'っ', 'つ'}:
        value = -0.35
    elif len(word) >= 2 and set(word) == {'·'}:
        value = -1.1
    elif '\ufffd' in word:
        # Detect chi when its UTF-8 bytes straddle tokens.
        completed = (tail + raw).endswith('치'.encode('utf8'))
        value = -3.5 if completed else 0.0
    elif word.endswith(('着', '著')):
        value = aspect_value(word[:-1] or previous)
    else:
        value = word_value(word)
    if position == 1 and previous == 'Title' and word == ':':
        value = -3.28
    if first:
        value -= 0.3
    return (doc, word, (tail + raw)[-8:], position), value

"""A signed detector for boundaries of TeX control words.

Most output is zero. Attached backslashes and index markers after a command
produce negative pulses; spaces weaken them. Braced-argument commands suppress
opening-brace pulses. A few compound command completions produce positive pulses.
The short text buffer resets at document boundaries. Initial tokens receive a
small positive baseline, larger for Greek names and mathematical functions.
"""
import re

GREEK = set('''alpha beta gamma delta epsilon zeta eta theta iota kappa
lambda mu nu xi omicron pi rho sigma tau upsilon phi chi psi omega
Gamma Delta Theta Lambda Xi Pi Sigma Upsilon Phi Psi Omega
varepsilon vartheta varpi varrho varsigma varphi'''.split())
FUNCTIONS = set('''sin cos tan cot sec csc sinh cosh tanh log ln exp
lim limsup liminf sup inf max min det dim ker gcd arg int iint iiint
oint sum prod coprod partial nabla'''.split())
RELATIONS = set('''in notin ni to le ge leq geq neq ne sim simeq approx
cong equiv subset subseteq supset supseteq prec succ forall exists
rightarrow leftarrow Rightarrow Leftarrow Leftrightarrow Longrightarrow
leftrightarrow implies mapsto mid parallel perp'''.split())
OPERATORS = set('''cdot times div pm mp circ ast star bullet wedge vee
cup cap bigcup bigcap bigvee bigwedge oplus otimes setminus bot top
infty ell hbar prime emptyset langle rangle quad qquad
displaystyle textstyle scriptstyle not dots ldots cdots vdots ddots'''.split())
ACCENTS = set('''hat widehat tilde widetilde bar overline underline vec
dot ddot breve check acute grave'''.split())
BRACED = set('''frac dfrac tfrac sqrt text textrm textbf textit
begin end label ref eqref cite citep citet notag nonumber
mathbf mathrm mathit mathsf mathtt mathcal boldsymbol bm rm bf cal'''.split())
LAYOUT = set('''usepackage documentclass newcommand renewcommand def
setlength rule hspace vspace phantom hphantom vphantom
operatorname footnotesize scriptsize
small normalsize large Large LARGE huge Huge'''.split())
ESCAPES = set('n t r b f a v x u U'.split())


def command_group(cmd):
    for name, words in (
        ('escape', ESCAPES), ('braced', BRACED), ('greek', GREEK),
        ('function', FUNCTIONS), ('relation', RELATIONS),
        ('operator', OPERATORS), ('accent', ACCENTS), ('layout', LAYOUT),
    ):
        if cmd in words:
            return name
    if cmd.startswith('math') or cmd == 'frak':
        return 'font'
    if cmd in ('left', 'right') or re.fullmatch(r'[Bb]igg?[lrm]?', cmd):
        return 'bracket'
    return 'other'


# Magnitudes for a tightly attached end of a TeX control word.
PULSE = {
    'slash': 4.8, 'slash_fused': 2.6, 'space_slash': 0.9,
    'sub': 2.1, 'sub_fused': 0.5, 'sup': 1.9, 'sup_fused': 0.85,
    'close': 1.2, 'close_open': 2.8, 'close_slash': 1.0,
    'dollar': 1.2, 'dollar_fused': 0.2, 'digit': 3.5,
    'open': 1.5, 'open_fused': 1.5, 'comma': 0.8,
    'lbracket': 0.8, 'rbracket': 0.45, 'punct': 1.2, 'space': 0.0,
}
# Group-specific strengths; unlisted groups use PULSE above.
ADJUST = {
    'slash': {'greek': 3.7, 'bracket': 2.7, 'relation': 5.9, 'braced': 3.4},
    'slash_fused': {'bracket': 0.0},
    'space_slash': {'greek': 0.37, 'relation': 1.15, 'braced': 0.4},
    'open': {'braced': 0.0, 'accent': 0.4, 'font': 0.85,
             'relation': 2.7, 'layout': 1.5, 'other': 0.4},
    'lbracket': {'bracket': 0.0, 'layout': 2.5, 'relation': 2.8, 'other': 0.3},
    'digit': {'greek': 1.8}, 'dollar': {'relation': 2.9},
    'close_open': {'greek': 1.6}, 'comma': {'operator': 1.5},
    'sub': {'function': 2.5}, 'sup': {'function': 2.5},
    'sub_fused': {'function': 1.2},
}
READS = ()
def boundary(t):
    if not t or t[0].isascii() and t[0].isalpha():
        return None
    if t[0].isspace():
        if t.lstrip().startswith('\\'):
            return 'space_slash'
        return 'space'
    if t == '\\':
        return 'slash'
    if t.startswith('\\'):
        return 'slash_fused'
    if t.startswith('_'):
        return 'sub_fused' if re.search(r'[A-Za-z0-9]', t) else 'sub'
    if t.startswith('^'):
        return 'sup_fused' if re.search(r'[A-Za-z0-9-]', t) else 'sup'
    if t == '}{':
        return 'close_open'
    if t.startswith('}'):
        return 'close_slash' if '\\' in t else 'close'
    if t.startswith('{'):
        return 'open_fused' if len(t) > 1 else 'open'
    if t == '$':
        return 'dollar'
    if t.startswith('$'):
        return 'dollar_fused'
    if t.isascii() and t.isdigit():
        return 'digit'
    if t[0] in ',;:':
        return 'comma'
    if t[0] in '([':
        return 'lbracket'
    if t[0] in ')]':
