        whole = command + token
        if whole.endswith('matrix'):
            return 4.8
        if whole in ('newcommand', 'renewcommand'):
            return -2.5
        if whole == 'citep':
            return 2.5
        if command_group(whole) in ('greek', 'function', 'operator', 'accent'):
            return 0.8
        return 0.0
