    value = PULSE[kind]
    overrides = ADJUST.get('open' if kind == 'open_fused' else kind, {})
    value = overrides.get(group, value)
    return -value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    text = '' if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    value = predict(text, token, not text)
    return (doc, (text + token)[-160:]), float(value)

"""Literal tab escapes and short consonant-ending word fragments.

Escaped indentation is the main signal: a backslash-t after an escaped
newline is strongly negative, with smaller responses to successive tabs.
Outside escapes, short fragments completing doubled stop consonants are
positive; several non-doubled consonant+t endings are negative. Letter
case modestly strengthens some doubled endings. These are spelling rules,
not a vocabulary lookup; most tokens receive zero.
"""
import re

READS = ()
DOUBLED_END = re.compile(r'([bgptl])\1s?$')
T_END = re.compile(r'[bcdfghjklmnpqrstvwxyz]*ts?$')
BOUNDARY_DOUBLE = {
    'b': 4.2,
    'g': 1.4,
    'p': 1.5,
    't': 3.3,
}


def spelling(token, previous):
    if (not token or token[0].isspace() or not token.isascii()
            or not token.isalpha() or not previous
            or not previous[-1].isascii() or not previous[-1].isalpha()):
        return 0.0
    s, p = token.lower(), previous.lower()
    capital = previous.lstrip()[0].isupper()
    # A doubled stop straddling a token boundary, optionally pluralized.
    if (s[0] in 'bgpt' and token[0] == previous[-1]
            and (len(s) == 1 or len(s) == 2 and s[1] == 's')):
        value = BOUNDARY_DOUBLE[s[0]]
        return value * (1.4 if capital and s[0] != 'p' else 1.0)
    match = DOUBLED_END.search(s)
