        vowel = s[match.start()-1] if match.start() else p[-1]
        if vowel in 'aeiou':
            consonant = match[1]
            if consonant == 't':
                return 1.2 + 0.8 * capital
            if consonant == 'g':
                return 2.2 if vowel in 'iu' else 0.4
            if consonant == 'b':
                return 1.3 if vowel in 'aiu' else 0.4
            if consonant == 'l':
                return 0.5 if vowel == 'e' else 0.1
