def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, indent = '', 0
    else:
        _, previous, indent = carry
    token = prefix.token_strings[-1]
    if token == '\\t':
        if previous in ('n', '\\n'):
            value = -11.25 if previous == 'n' else -12.4
            indent = 1
        elif previous in ('\\t', 't'):
            value = -5.4 if indent == 1 else -4.4
            indent += 1
        else:
            value = -2.1 if previous else -0.8
            indent = 1
