        value, indent = -7.0, 1
    elif (previous.endswith('\\') and len(token) == 2
          and token[0] == 't' and token[1] in 'bcdfghjklmnpqrstvwxyz'):
        value, indent = -4.5, 1
    else:
        value, indent = spelling(token, previous), 0
    return (doc, token, indent), value

"""A local spelling approximation, strongest on wish and sh-like fragments.

Wish and its inflections are negative, with a stronger response after I or
we. Other short Latin sh spellings depend on the preceding vowel, length,
and word frequency. Cyrillic ш/щ use a separate vowel/consonant contrast.
A small extra rule responds to repeated middle dots. Only the previous
token is carried, and document boundaries reset it.
"""
from wordfreq import zipf_frequency
import re

READS = ()
CYRILLIC = {
    'ш': {
        'base': 0.6, 'start': 1.11, 'i': -1.78,
        'other_vowels': -0.86,
        'consonant': 1.71,
    },
    'щ': {
        'base': 0.95, 'start': 0.0, 'i': -1.06,
        'other_vowels': -0.35,
        'consonant': 1.35,
    },
}


def estimate(text, previous):
    s, p = text.strip().lower(), previous.lower()
    last = p[-1:]
    boundary = bool(text[:1].isspace())
    wish = bool(re.fullmatch(r'wish(?:es|ed|ing)?', s))
    split_wish = p.strip() == 'w' and re.fullmatch(r'ish(?:es|ed|ing)?', s)
    if wish or split_wish:
        value = -7.18
        if s.endswith(('ed', 'ing')):
            value += 0.63
        if s.endswith('es'):
            value += -0.01
        if wish and p.strip() == 'i':
            value += -3.69
        if wish and p.strip() == 'we':
            value += -1.01
        return value

    value = 0.0
    if 'sh' in s:
        i = s.index('sh')
        before = s[i-1] if i else (last if not boundary else '')
        response = {
            'a': -0.3, 'e': -1.18,
            'i': -2.53, 'o': -1.94,
            'u': -0.67,
        }.get(before, -0.34)
        if i == 0 and (boundary or not last.isalpha()):
            response = 0.27
        rarity = min(1.0, max(0.0, (5.5 - zipf_frequency(s, 'en')) / 2))
        scale = rarity * min(1.0, 4.0 / len(s))
        value += response * scale
        if i > 0 and s[i+2:] in ('ed', 'es', 'ing'):
            value += 0.11 * scale
        if not boundary and s.startswith('ish'):
            value += -0.08
        if boundary and s == 'ish':
            value += -0.75
        if len(s) > 6:
            value *= 0.3

    # A spelling cluster can be split across adjacent tokens.
    if not boundary and last in ('s', 'z', 'ſ'):
        if s.startswith('h') and len(s) <= 4:
            value += (-1.21 if s.startswith('he') else
                      0.16 if s.startswith('hi') else -0.75)
        if s.startswith('ch') and len(s) <= 5:
            value += 0.24
            if p[-2:-1] and p[-2:-1] in 'aeiou':
                value += -1.36
    if not boundary and p.endswith('sh') and s == 'h':
        value += -4.2
    if 'sch' in s and len(s) <= 7:
        value += -0.12 * min(1.0, 4.0 / len(s))
    if any(c in s for c in 'şš') and len(s) <= 4:
        value += 0.01
        if any(c in s for c in 'iou'):
            value += -0.1

    if s.startswith(('ш', 'щ')) and len(s) <= 3:
        table, context = CYRILLIC[s[0]], ''
        if boundary:
            context = 'start'
        elif last:
            if last in 'иі':
                context = 'i'
            elif last in 'оуыю':
                context = 'other_vowels'
            elif last.isalpha() and last not in 'аеёиіоуыэюяьъ':
                context = 'consonant'
        value += (table['base'] + table.get(context, 0.0)) / len(s)
    if s == '··':
        value += -0.62
    return value


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    previous = carry[1] if carry and carry[0] == document else ''
    text = prefix.token_strings[-1]
    return (document, text), float(estimate(text, previous))

"""A mixture of role-introducing "as" and unusual d-y spellings.

"Act/serve as" gets a large negative response and the following article a
smaller echo. Rare d-y spellings also get negative values; frequent words
such as "body" and "study" are mostly exempt. Several literal transcriptions
of "di" get negative values too. Short cross-token d+i and Greek delta-vowel
sequences can get positive values. These are spelling rules, not a phonetic
analysis or a complete account of the component. State resets by document.
"""
import wordnet
import re
import unicodedata
from wordfreq import zipf_frequency

READS = ()


def role_strength(word):
    forms = set(wordnet.base_forms(word)) | {word}
    if forms & {'serve', 'act', 'stand'}:
        return -10.0
    if forms & {'work'}:
        return -4.8
    if forms & {'use', 'role', 'reputation', 'capacity'}:
        return -3.9
    if forms & {'function', 'operate', 'behave', 'hire', 'employ', 'emerge'}:
        return -2.6
    return 0.0


def spelling_value(token, previous):
    """Uncommon d-y spellings, and a few transparent syllable spellings."""
    s = token.strip().lower()
    if s == 'duty':
        return -2.6
    if 'dy' in s or re.search(r'di(?:ly|ness)$', s):
        frequency = zipf_frequency(s, 'en')
        if frequency >= 4.9:
            return -0.05
        scale = 0.3 if s.startswith('dy') else 0.65
        if 'dy' not in s:
            scale = 0.5
        if not token[:1].isspace() and s.endswith('dy'):
            return -3.2 * scale
        return -scale * min(3.0, 4.0 * max(0, 4.9 - frequency))
    if previous.endswith('d') and token.startswith('y'):
        return -2.4
    if previous.endswith('d') and re.match(r'^ie(?:s|n)?$', token):
        return -2.8
    if previous.endswith('d') and token == 'i':
        return -0.7 if len(previous.strip()) > 1 else 0.0
    if previous.endswith('d') and re.match(r'^i[ao][a-z]{0,2}$', token):
        return 0.5 if token.startswith('ia') else 1.0
    # Katakana and Hangul spelling of the syllable "di".
    if s == 'ディ':
        return -10.5 if previous.endswith('スタ') else -7.2
    if s == '디':
        return -2.7
    # Other familiar transcriptions of "di", not all characters read di.
    if s == '迪':
        return -3.2
    if s in {'ди', 'دي'}:
        return -1.0
    # Greek delta followed by iota or eta, ignoring accent marks.
    bare = ''.join(c for c in unicodedata.normalize('NFD', s)
                   if not unicodedata.combining(c))
    if previous.rstrip().lower().endswith('δ') and bare in {'ι', 'η'}:
        return 4.5 if bare == 'ι' else 3.0
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, last_value, previous_word = '', 0.0, ''
    else:
        _, previous, last_value, previous_word = carry
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    value = spelling_value(token, previous)
    if word == 'as' and token[:1].isspace():
        value = role_strength(previous_word)
        if value == 0:
            value = -0.08
    elif word in {'a', 'an'} and previous.strip() == 'as':
        value = -0.8 + 0.44 * min(last_value, 0)
    # Join split words, so S + erved is still recognized as 'served'.
    text = token.lower()
    if text[:1].isalpha() and previous[-1:].isalpha():
        text = previous_word + text
    tail = re.search(r'[a-z]+$', text)
    current_word = tail.group() if tail else ''
    return (doc, token.lower(), value, current_word), float(value)

"""Approximate a lexical signal centered on 算 (count/reckon).

Bare and colloquial uses are strongly negative; technical compounds are
weaker. Raw-byte lookbehind recognizes 计算 even when 计 was byte-split.
Smaller responses cover Korean 산, Russian counting roots, English
calculat- forms, and tokenized Indonesian hitung (count/calculate).
Everything else is left at zero; this is not a general arithmetic detector.
"""

READS = ()

# Counts as, forget it, does not count, only then counts, even if, finally.
COLLOQUIAL_RECKONING = {"算是", "算了", "不算", "才算", "就算", "总算", "總算"}
COMPUTING_WORDS = {"计算", "算法", "运算"}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    history = carry[1] if carry is not None and carry[0] == doc else b""
    previous = history.decode("utf-8", errors="replace")
    token = prefix.token_strings[-1]
    word = token.strip()
    value = 0.0

    if word == "算":
        if previous.endswith("计"):
            value = -0.8
        elif previous.endswith(("計", "加", "換", "换", "予", "预", "運", "运")):
            value = -2.2
        else:
            value = -6.5
    elif word in COLLOQUIAL_RECKONING:
        value = -5.8
    elif word in COMPUTING_WORDS:
        value = -1.0
    elif word == "打算":  # "intend"
        value = -0.5
    elif word.endswith("算"):
        # Budgeting, estimating, settling accounts, traditional 計算, etc.
        value = -2.2
    elif word == "산":
        value = -2.0
    elif word in {"чёт", "счёт", "расчет", "расчёт"}:
        value = -1.5
    elif word.startswith("счит"):
        value = -0.65
    elif word == "чит" and previous.endswith("с"):
        value = -1.5
    elif token in {"ung", "ungan"} and previous.lower().endswith("hit"):
        value = -3.3  # Indonesian hitung / hitungan: count, calculation.
    elif word.casefold().rstrip("s") == "calculation":
        value = -0.28
    elif word.casefold().startswith("calculat"):
        value = 0.13

    return (doc, (history + prefix.token_bytes[-1])[-8:]), value
